L["Blizzard's aura borders on the buffs, debuffs and weapon enchants, with every EllesmereUI bar feature."] = "Blizzards Aurenränder bei Stärkungszauber, Schwächungszauber und Waffenverzauberungen mit allen EllesmereUI Leistenfunktionen."
L["Blizzard's buff bar art, or the classic cast bar frame, with every EllesmereUI tracked bar feature."] = "Blizzards Buffleistengrafik oder der klassische Zauberleistenrahmen mit allen EllesmereUI Verfolgungsleistenfunktionen."
L["Blizzard's cast bar art, or the classic cast bar frame, with every EllesmereUI cast bar feature."] = "Blizzards Zauberleistengrafik oder der klassische Zauberleistenrahmen mit allen EllesmereUI Zauberleistenfunktionen."
L["Blizzard's Edit Mode snapping may not work correctly until you reload your UI."] = "Das Einrasten im Editier Modus von Blizzard funktioniert möglicherweise erst nach einem Neuladen des UI korrekt."
L["Blizzard's frame art, portraits and bar shapes, or the classic frames, with every EllesmereUI frame feature."] = "Blizzards Fenstergrafik, Porträts und Leistenformen oder die klassischen Fenster mit allen EllesmereUI Fensterfunktionen."
L["Blizzard's health and cast bar art, or the classic flat plates, with every EllesmereUI nameplate feature."] = "Blizzards Gesundheits- und Zauberleistengrafik oder die klassischen flachen Plaketten mit allen EllesmereUI Namensplakettenfunktionen."
L["Blizzard's meter window and bar art, or a window in the classic chat tabs' border, with every EllesmereUI meter feature."] = "Blizzards Meterfenster und Leistengrafik oder ein Fenster im klassischen Chat Reiterrahmen mit allen EllesmereUI Meterfunktionen."
L["Blizzard's own chat window, tabs and input box, or the same window with the classic tab art, with every EllesmereUI chat feature."] = "Blizzards eigenes Chatfenster, Reiter und Eingabefeld oder dasselbe Fenster mit der klassischen Reiter-Grafik mit allen EllesmereUI Chatfunktionen."
L["Blizzard's own frame and button art, with EllesmereUI's features."] = "Blizzards eigene Fenster- und Schaltflächengrafik mit den Funktionen von EllesmereUI."
L["Blizzard's own friends window and cards, with the EllesmereUI class icons, class-coloured names and region icons added. Both stock styles look the same here."] = "Blizzards eigenes Freundefenster und Karten mit hinzugefügten EllesmereUI Klassensymbolen, klassenfarbenen Namen und Regionalsymbolen. Beide Standardstile sehen hier gleich aus."
L["Blizzard's own tracker, with every EllesmereUI tracker feature. Both stock styles look the same here."] = "Blizzards eigene Verfolgung mit allen EllesmereUI Verfolgungsfunktionen. Beide Standardstile sehen hier gleich aus."
L["Blizzard's raid frame edge and highlights, or the classic ones, with every EllesmereUI raid frame feature."] = "Blizzards Schlachtzugsfensterrand und Hervorhebungen oder die klassischen mit allen EllesmereUI Schlachtzugsfensterfunktionen."
L["Blizzard's round minimap and header, or the classic ring, with every EllesmereUI minimap feature."] = "Blizzards runde Minikarte und Kopfzeile oder der klassische Ring mit allen EllesmereUI Minikartenfunktionen."
L["Blizzard's rounded button art, or the classic square slots, with every EllesmereUI bar feature."] = "Blizzards abgerundete Schaltflächengrafik oder die klassischen quadratischen Plätze mit allen EllesmereUI Leistenfunktionen."
L["Blizzard's rounded cooldown icons, or the classic square slots, with every EllesmereUI icon feature."] = "Blizzards abgerundete Abklingzeitsymbole oder die klassischen quadratischen Plätze mit allen EllesmereUI Symbolfunktionen."
L["Blizzard's windows now match the EllesmereUI theme with a WoW 2.0 Dark Theme, from the Dungeon Journal to the Auction House and beyond."] = "Blizzards Fenster entsprechen jetzt dem EllesmereUI Design mit einem dunklen WoW 2.0 Theme, vom Dungeontagebuch bis zum Auktionshaus und darüber hinaus."
