L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "Färbt die Gesundheitsleiste basierend auf der verbleibenden Gesundheit ein, anstatt eine einfarbige Farbe zu nutzen. 'Klassisch' verläuft von Grün bei voller Gesundheit über Gelb bis Rot bei leerer Gesundheit. 'Eigene Farben' blendet zwischen den drei Farbfeldern dieser Zeile über – voll (100%), halb (50%) und leer (0%). 'Klassenreaktiv' zeigt bei voller Gesundheit die Klassenfarbe und geht in die Farben für 50% und 0% über, wenn die Einheit Schaden erleidet. 'Aus' überlässt den einfarbigen Füllfarbfeldern die Steuerung; der Farbverlauf unten wird in jedem Fall angewendet."
L["Colors an attackable unit's level by difficulty, as the default UI does."] = "Färbt die Stufe einer angreifbaren Einheit nach Schwierigkeit ein, wie es das Standard UI tut."
L["Colors are shared globally from the \"%1$s\" profile.\nSwitch to it (or set Pull Colors From to this profile) to edit."] = "Farben werden global aus dem Profil \"%1$s\" geteilt.\nWechsle zu diesem (oder stelle 'Farben beziehen von' auf dieses Profil), um sie zu bearbeiten."
L["Colors level text by difficulty, from grey (trivial) through green, yellow and orange to red (5+ levels above you)."] = "Färbt den Stufentext nach Schwierigkeit ein, von Grau (trivial) über Grün, Gelb und Orange bis Rot (5+ Stufen über Dir)."
L["Colors the cast segment during which your interrupt will be available."] = "Färbt den Zauberabschnitt ein, in dem Dein Unterbrechungszauber verfügbar sein wird."
