L["Include your complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. On import this replaces the recipient's overrides entirely."] = "Enthält Dein vollständiges Überschreibungs Setup: Spezialisierungs- und bedingte Überschreibungswerte, Gruppen, deren benutzerdefinierte Freigabemodus Layouts und Stärkungszauber Manager Überschreibungen. Beim Import ersetzt dies die Überschreibungen des Empfängers vollständig."
