L["Show a reminder when your Warlock's active pet isn't one of the demons picked in Allowed Demons. A demon only counts while its summon spell is known, so leaving only Felguard picked stays silent for specs/builds that haven't talented Summon Felguard."] = "Zeigt eine Erinnerung an, wenn der aktive Begleiter Deines Hexenmeisters keiner der unter „Erlaubte Dämonen“ ausgewählten Dämonen ist. Ein Dämon zählt nur, wenn sein Beschwörungszauber bekannt ist. Ist ausschließlich die Teufelswache ausgewählt, bleibt die Erinnerung daher für Spezialisierungen oder Konfigurationen ohne das Talent „Teufelswache beschwören“ stumm."
