L["The background colour behind Dark Mode bars (Unit Frames, Raid Frames, Resource Bars)."] = "Die Hintergrundfarbe hinter Leisten im dunklen Modus (Einheitenfenster, Schlachtzugsfenster, Ressourcenleisten)."
L["The Combat Indicator is not available for the Focus frame."] = "Der Kampfindikator ist für das Fokusfenster nicht verfügbar."
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "Die Anzeigesprache für das EllesmereUI Optionsfenster. 'Auto' folgt Deinem Spielclient. Nicht übersetzter Text fällt auf Englisch zurück."
L["the EllesmereUI theme"] = "das EllesmereUI Theme"
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "Das genaue Gegenteil von Himmelsreiten (in der Luft): Alles, was nicht auf einem gleitfähigen Reittier oder in Fluggestalt in der Luft ist, einschließlich des Stehens auf dem Boden."
L["The flat fill colour bars use when Dark Mode is enabled (Unit Frames, Raid Frames, Resource Bars)."] = "Die einfarbige Füllfarbe, die Leisten im dunklen Modus verwenden (Einheitenfenster, Schlachtzugsfenster, Ressourcenleisten)."
L["the Frame Source to be EllesmereUI"] = "dass die Fensterquelle EllesmereUI ist"
L["the Modern background style"] = "der moderne Hintergrundstil"
L["The original frames, rings and slots where the game has them, with EllesmereUI's features."] = "Die ursprünglichen Fenster, Ringe und Plätze dort, wo das Spiel sie hat, mit den Funktionen von EllesmereUI."
L["The pasted string could not be read completely. Please paste it again."] = "Der eingefügte String konnte nicht vollständig gelesen werden. Bitte erneut einfügen."
L["the Randomly trigger"] = "der Auslöser 'Zufällig'"
L["The Ring of Valor"] = "Ring des Valor"
L["These are the same settings found on each module's own pages, not separate ones."] = "Dies sind dieselben Einstellungen, die sich auch auf den jeweiligen Modulseiten befinden, keine separaten."
L["These settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Diese Einstellungen bevorzugen Bildrate und visuelle Klarheit gegenüber Umgebungsdetails. Texturen bleiben hochauflösend."
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "Diese Spezialisierungen enthalten Überschreibungswerte, die von keinem Gruppen Bearbeitungsmodus mehr erreicht werden können (hinterlassen durch Mitgliedschaftsänderungen). Sie gelten weiterhin. Entferne eine, um diese Spezialisierung zum gemeinsamen Standard zurückzuführen."
L["Thick"] = "Dick"
L["Thickness"] = "Dicke"
L["Thin Line Bottom"] = "Dünne Linie unten"
L["Thin Line Top"] = "Dünne Linie oben"
L["This bar sizes its blocks itself, so the width is not this block's to choose."] = "Diese Leiste skaliert ihre Blöcke selbst, daher kann die Breite für diesen Block nicht gewählt werden."
L["This bar will only show if you have an enemy targeted"] = "Diese Leiste wird nur angezeigt, wenn Du einen Gegner als Ziel hast"
L["This block is already the 'Fill Remaining Space' block. Check another block to move the role."] = "Dieser Block ist bereits der Block 'Verbleibenden Platz füllen'. Wähle einen anderen Block, um diese Rolle zu verschieben."
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "Dies kann nicht ändern, welche Zauber im Blizzard CDM verfolgt werden.\nEs wird empfohlen, auch Dein Blizzard CDM Layout für jede hier gewählte Spezialisierung zu teilen."
L["This cannot be undone. Export your own profile as a backup first."] = "Dies kann nicht rückgängig gemacht werden. Exporte zuerst Dein eigenes Profil als Backup."
L["This condition is coming in a future update."] = "Diese Bedingung folgt in einem zukünftigen Update."
L["This control recently changed direction: it now copies FROM the frame you choose. Confirming will copy all shared settings FROM %1$s TO %2$s."] = "Steuerungskontrolle hat die Richtung geändert: Sie kopiert nun VON dem gewählten Fenster. Bestätigen kopiert alle geteilten Einstellungen VON %1$s NACH %2$s."
L["This element cannot use group-based visibility."] = "Dieses Element kann keine gruppenbasierte Sichtbarkeit nutzen."
L["This element doesn't support both Height and Width matching"] = "Dieses Element unterstützt nicht gleichzeitig Höhen- und Breitenanpassung."
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "Dieses Element wird angezeigt, sobald EINE Einblenden-Bedingung zutrifft. Ausblenden behält seine Bedeutung in beiden Übereinstimmungsmodi bei: Ein aktivierter Ausblenden-Haken blendet in jeder Zeile immer aus."
L["This element will only show while you are inside a house or plot"] = "Dieses Element wird nur angezeigt, während Du dich in einem Haus oder auf einem Grundstück befindest."
L["This element will only show while you are mounted"] = "Dieses Element wird nur angezeigt, während Du aufgesessen bist."
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "Dieser Export enthält profilübergreifende Einstellungen (Komfortfunktionen, HoverCast etc.), die beim Importeur überschrieben werden. NICHT EMPFOHLEN für die öffentliche Weitergabe."
L["This feature requires Snap Elements to be enabled"] = "Diese Funktion erfordert, dass 'Elemente einrasten' aktiviert ist."
L["This frame's source changes require a UI reload to take effect."] = "Änderungen an der Quelle dieses Fensters erfordern ein Neuladen des UI."
L["This group's custom Debuff Manager can only be activated or edited while playing one of its specs."] = "Der benutzerdefinierte Schwächungszauber-Manager dieser Gruppe kann nur aktiviert oder bearbeitet werden, während eine ihrer Spezialisierungen gespielt wird."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "Dies ist das Zauber-Warteschlangenfenster. Es verhindert das Reihen zu vieler Zauber auf einmal, was sich schwammig anfühlen kann. Empfohlen: mindestens 200 + lokaler Ping. Wenn Du unsicher bist, belasse es bei 400."
L["This is where you can control the settings of Unlock Mode.\n\nElements can be repositioned by dragging or arrow keys (+shift)\nAnchor, Height Match, or Width match any element.\nSnapping is based on closest element, but you can snap only to\n a specific element via right click or the settings icon."] = "Hier steuerst Du die Einstellungen des Freigabemodus.\n\nElemente können durch Ziehen oder Pfeiltasten (+ Umschalt) verschoben werden.\nVerankere, passe Höhe oder Breite an jedes Element an.\nEinrasten basiert auf dem nächsten Element, kann aber per Rechtsklick\noder Einstellungssymbol auf ein bestimmtes Element beschränkt werden."
L["This makes it so the width of the cast bar includes the icon, rather than placing it to the left of the cast bars width."] = "Bewirkt, dass die Breite der Zauberleiste das Symbol beinhaltet, anstatt es links außerhalb der Leistenbreite zu platzieren."
L["This module can't be overridden. Exit the override editing session to open it."] = "Dieses Modul kann nicht überschrieben werden. Beende die Bearbeitungssitzung der Überschreibung, um es zu öffnen."
L["This option does not apply to the player frame."] = "Diese Option gilt nicht für das Spielerfenster."
L["This option is not available on the player frame"] = "Diese Option ist auf dem Spielerfenster nicht verfügbar."
L["This option is only available for formats that display a percentage."] = "Nur verfügbar für Formate, die einen Prozentwert anzeigen."
L["This option is only available for the Custom Color Theme"] = "Nur verfügbar für das benutzerdefinierte Farb Theme"
L["This option is only available when Portrait Mode is Detached."] = "Nur verfügbar, wenn der Porträtmodus auf 'Lösgetrennt' steht."
L["This option requires a Border Size above 0."] = "Erfordert eine Rahmengröße über 0."
L["This option requires a Class Icon other than None."] = "Erfordert ein anderes Klassensymbol als 'Keine'."
L["This option requires a detached position to be active."] = "Erfordert eine aktive, lösgetrennte Position."
L["This option requires a dropdown selection other than Above Health Bar"] = "Erfordert eine andere Auswahl im Dropdown Menü als 'Über Gesundheitsleiste'"
L["This option requires a Duration Text position other than None"] = "Erfordert eine andere Dauer Textposition als 'Keine'"
L["This option requires a Glow Type other than None"] = "Erfordert einen anderen Leuchttyp als 'Keiner'"
L["This option requires a Name Text position other than None"] = "Erfordert eine andere Namenstext Position als 'Keine'"
L["This option requires a Stacks Text position other than None"] = "Erfordert eine andere Stapel Textposition als 'Keine'"
L["This option requires a text position other than none."] = "Erfordert eine andere Textposition als 'Keine'."
L["This option requires a text selection other than none."] = "Erfordert eine andere Textauswahl als 'Keine'."
L["This option requires a Type Icon Position other than None"] = "Diese Option erfordert eine andere Typ Symbolposition als 'Keine'."
L["This option requires a Type Icon Position other than None."] = "Diese Option erfordert eine andere Typ Symbolposition als 'Keine'."
L["This option requires Class Resource to be set to Modern."] = "Erfordert, dass die Klassenressource auf 'Modern' eingestellt ist."
L["This option requires Combine Spell Name and Target to be disabled."] = "Erfordert, dass 'Zaubernamen und Ziel kombinieren' deaktiviert ist."
L["This option requires Portrait Mode to be set to Detached."] = "Erfordert, dass der Porträtmodus auf 'Lösgetrennt' eingestellt ist."
L["This option requires Show Level."] = "Diese Option erfordert 'Stufe anzeigen'."
L["This option requires the position setting to be detached"] = "Erfordert, dass die Positionseinstellung lösgetrennt ist"
L["This overwrites this frame's current settings. Frame position, visibility, and enable state are not changed."] = "Überschreibt die aktuellen Einstellungen dieses Fensters. Position, Sichtbarkeit und Aktivierungszustand bleiben unverändert."
L["This page is excluded from overrides."] = "Diese Seite ist von Überschreibungen ausgeschlossen."
L["This profile string does not carry any global settings."] = "Dieser Profil String enthält keine globalen Einstellungen."
L["This profile string does not carry any override data."] = "Dieser Profilstring enthält keine Überschreibungsdaten."
L["This profile string does not carry any Window & Tooltip Skins settings."] = "Dieser Profil-String enthält keine Einstellungen für Fenster- & Tooltip Skins."
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "Profil wurde bei %1$d%% UI Skalierung erstellt; Deine ist %2$d%%. UI Skalierung anpassen? Gilt profilübergreifend, kann aber jederzeit zurückgesetzt werden."
L["This resets every EUI addon, not just the current one."] = "Setzt jedes EUI Addon zurück, nicht nur das aktuelle."
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "Dies ist ein VOLLSTÄNDIGER ACCOUNT-Export. Er ersetzt Deine accountweiten Einstellungen (Komfortfunktionen, HoverCast, CDM-Setup, Anker, UI Skalierung etc.) durch die des Absenders. Andere Profile bleiben erhalten; gleichnamige werden ersetzt."
L["This unit uses the Blizzard default frame -- there are no EllesmereUI settings to configure here."] = "Diese Einheit nutzt das Blizzard-Standardfenster – hier gibt es keine EllesmereUI Einstellungen."
L["This unit's frame is hidden -- there are no EllesmereUI settings to configure here."] = "Das Fenster dieser Einheit ist ausgeblendet – hier gibt es keine EllesmereUI Einstellungen."
L["This will create a fully unique Buff Manager for this conditional group. Changes made to your default Buff Manager will no longer affect it."] = "Dies erstellt einen vollständig eigenständigen Stärkungszauber-Manager für diese bedingte Gruppe. Änderungen an Deinem Standard Stärkungszauber Manager wirken sich nicht mehr darauf aus."
L["This will create a fully unique Buff Manager for this override group. Changes made to your default Buff Manager will no longer affect these specs."] = "Dies erstellt einen vollständig eigenständigen Stärkungszauber-Manager für diese Überschreibungsgruppe. Änderungen an Deinem Standard Stärkungszauber Manager wirken sich nicht mehr auf diese Spezialisierungen aus."
L["This will create a fully unique Debuff Manager for this conditional group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect it."] = "Dies erstellt einen vollständig eigenständigen Schwächungszauber Manager für diese bedingte Gruppe. Aktuelle Einstellungen werden kopiert; spätere Änderungen am Standard betreffen diese Gruppe nicht mehr."
L["This will create a fully unique Debuff Manager for this override group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect these specs."] = "Dies erstellt einen vollständig eigenständigen Schwächungszauber Manager für diese Überschreibungsgruppe. Aktuelle Einstellungen werden kopiert; spätere Änderungen am Standard betreffen diese Spezialisierungen nicht mehr."
L["This will not reset addon-specific Quick Setup."] = "Setzt die addon spezifische Schnelleinrichtung nicht zurück."
L["This will replace YOUR Blizz UI Enhanced settings (the Window Skins and Tooltips, Menus & Popups tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "Ersetzt DEINE Einstellungen für die erweiterte Blizzard UI (Skins, Tooltips, Menüs & Popups) über ALLE Profile hinweg durch die des Absenders. Aktuelle Einstellungen gehen verloren."
