L["Shown on dead members being resurrected (LibResComm-1.0, bundled)."] = "Wird bei toten Mitgliedern angezeigt, die wiederbelebt werden (LibResComm-1.0, enthalten)."
L["Shows debuffs that match any checked Show filter (the default)."] = "Zeigt Schwächungszauber, die einem beliebigen aktivierten Anzeigefilter entsprechen (Standard)."
L["Shows every bar with placeholder icons while the options are open."] = "Zeigt jede Leiste mit Platzhaltersymbolen, solange die Optionen geöffnet sind."
L["Shows large amounts using K/M suffixes (284,208g becomes 284.2Kg) instead of the full grouped number. The tooltip always shows the exact amount."] = "Zeigt große Beträge mit K/M Suffixen (284.208g wird zu 284.2Kg) statt der vollständigen gruppierten Zahl. Der Tooltip zeigt immer den genauen Betrag."
L["Shows only debuffs that match every checked Show filter (dispel types count as one); opposites like Non-Player Auras with Cast By You show nothing."] = "Zeigt nur Schwächungszauber, die allen aktivierten Anzeigefiltern entsprechen (Banntypen zählen als einer); Gegensätze wie 'Nicht-Spieler Auren' mit 'Von Dir gewirkt' zeigen nichts."
L["Shows the bag icon next to the slot count."] = "Zeigt das Taschensymbol neben der Platzanzahl."
L["Shows the combat status text only while your character is in combat."] = "Zeigt den Kampfstatustext nur, während Dein Charakter im Kampf ist."
L["Shows the cost of the spell being cast on the power bar."] = "Zeigt die Kosten des gewirkten Zaubers auf der Ressourcenleiste."
L["Shows the frame while this unit is below full health; while enabled, a frame hidden by its visibility setting can still be clicked."] = "Zeigt das Fenster, solange diese Einheit nicht volle Gesundheit hat; wenn aktiviert, kann ein durch seine Sichtbarkeitseinstellung ausgeblendetes Fenster trotzdem angeklickt werden."
L["Shows the health text elements placed in Core Text Positions."] = "Zeigt die Gesundheitstextelemente, die in 'Haupttextpositionen' platziert sind."
L["Shows the last lines of each chat window again after a reload or relog."] = "Zeigt die letzten Zeilen jedes Chatfensters nach einem Neuladen oder erneutem Einloggen wieder an."
L["Shows the most important boss debuff (ICC, Ruby Sanctum, ToC, Ulduar, Naxxramas) as a large icon in the middle of the frame."] = "Zeigt den wichtigsten Boss-Schwächungszauber (ICC, Rubinsanktum, PdK, Ulduar, Naxxramas) als großes Symbol in der Mitte des Fensters."
L["Shows the network latency zone at the end of casts or channels, including queued spells."] = "Zeigt die Netzwerklatenzzone am Ende von Zaubern oder Kanalisierungen, einschließlich eingereihter Zauber."
L["Shows the spell icon over the portrait while casting and lets the bar use the full width."] = "Zeigt das Zaubersymbol beim Wirken über dem Porträt und lässt die Leiste die volle Breite nutzen."
L["Shows the stock rune or combo point frame here instead of the pips."] = "Zeigt hier das Standard Runen- oder Combopunktfenster statt der Punkte."
L["Shows your arena opponents. Left click targets, right click sets focus."] = "Zeigt Deine Arenagegner. Linksklick wählt als Ziel, Rechtsklick setzt den Fokus."
L["Shows your interrupt while your focus is casting."] = "Zeigt Deinen Unterbrechungszauber, während Dein Fokus zaubert."
L["Shows your interrupt while your focus or target is casting."] = "Zeigt Deinen Unterbrechungszauber, während Dein Fokus oder Ziel zaubert."
L["Shows your threat percentage on the target and focus frames while you are in combat with that unit."] = "Zeigt Deinen Bedrohungsprozentsatz auf Ziel- und Fokusfenster, solange Du mit dieser Einheit im Kampf bist."
