L["The bank opens anywhere from the Bags header; away from a banker it shows the last saved contents."] = "Die Bank lässt sich überall über die Taschen-Kopfzeile öffnen; fern eines Bankiers zeigt sie den zuletzt gespeicherten Inhalt."
