L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "Der Abklingzeiten Manager kann weit mehr als nur Abklingzeiten anzeigen: Er bietet auch Einstellungen pro Zauber, Leistenleuchten, Verfolgungsleisten und mehr! Sieh Dir ein paar Tipps und Tricks an, um mehr aus ihm herauszuholen."
L["The fallback must differ from\nthe main anchor target"] = "Die Ausweichoption muss sich vom\nHauptankerziel unterscheiden"
L["The gem could not be socketed."] = "Der Edelstein konnte nicht gesockelt werden."
L["The glow line is not shown on a vertical fill or with the From Left Edge placement"] = "Die Leuchtlinie wird bei vertikaler Füllung oder mit der Platzierung 'Vom linken Rand' nicht angezeigt"
L["The glow line is not shown on a vertical fill or with the From Right Edge placement"] = "Die Leuchtlinie wird bei vertikaler Füllung oder mit der Platzierung 'Vom rechten Rand' nicht angezeigt"
L["The glow line is not shown with Absorb Style None"] = "Die Leuchtlinie wird mit Absorptionsstil 'Keiner' nicht angezeigt"
L["The Lich King"] = "Der Lichkönig"
L["The native social window with class icons, class-coloured names, faction banners and invite auto-accept; friend actions and every social tab stay native."] = "Das native Sozialfenster mit Klassensymbolen, klassenfarbigen Namen, Fraktionsbannern und automatischer Annahme von Einladungen; Freundesaktionen und alle sozialen Reiter bleiben nativ."
L["The override group '%s' already provides the custom unlock mode for your current spec. Customize it there, or remove this spec from that group."] = "Die Überschreibungsgruppe '%s' stellt bereits den eigenen Freigabemodus für Deine aktuelle Spezialisierung bereit. Passe ihn dort an oder entferne diese Spezialisierung aus der Gruppe."
L["The personal resource display's bar frame, or the classic cast bar frame, on the health, power and class resource bars, with every EllesmereUI bar feature."] = "Der Leistenrahmen der persönlichen Ressourcenanzeige oder der klassische Zauberleistenrahmen, auf Gesundheits-, Ressourcen- und Klassenressourcen Leisten, mit allen EllesmereUI Leistenfunktionen."
L["The Pixel Glow settings this bar's per-icon glows use. The template never changes them."] = "Die Pixelleuchten Einstellungen, die die Symbolleuchten dieser Leiste nutzen. Die Vorlage ändert sie nie."
L["The scriptProfile CVar is enabled."] = "Die scriptProfile CVar ist aktiviert."
L["The socketed gem will be destroyed. Continue?"] = "Der gesockelte Edelstein wird zerstört. Fortfahren?"
L["The taintLog and scriptProfile CVars are enabled."] = "Die CVars taintLog und scriptProfile sind aktiviert."
L["The taintLog CVar is enabled."] = "Die taintLog CVar ist aktiviert."
L["The tracker always hides in arenas"] = "Der Tracker wird in Arenen immer ausgeblendet"
L["Thickness in pixels. -1 follows each debuff indicator's Border setting, 0 hides the dispel color border."] = "Dicke in Pixeln. -1 folgt der Rahmeneinstellung jedes Schwächungszauber Indikators, 0 blendet den Bannfarbrahmen aus."
L["This cannot be undone. Consider exporting this profile as a backup first."] = "Dies kann nicht rückgängig gemacht werden. Exportiere dieses Profil am besten zuerst als Sicherung."
L["This conditional is not active right now. Meet one of its conditions first (for example, enter the dungeon) so you can arrange the layout in its real context."] = "Diese Bedingung ist gerade nicht aktiv. Erfülle zuerst eine ihrer Bedingungen (betritt z. B. den Dungeon), damit Du das Layout im echten Kontext anordnen kannst."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\n"] = "Diese Funktion optimiert Deine Grafikeinstellungen im Spiel für die beste Kombination aus hohen FPS und visueller Klarheit.\n\nDu kannst alle Änderungen jederzeit rückgängig machen, indem Du auf \"Meine Einstellungen wiederherstellen\" klickst, was nach dem Optimieren erscheint.\n\n\nWas wir ändern:\n\n"
L["This glow is locked on its settings page."] = "Dieses Leuchten ist auf seiner Einstellungsseite gesperrt."
L["This group's custom Buff Manager can only be activated or edited while playing one of its specs."] = "Der eigene Stärkungszauber Manager dieser Gruppe kann nur aktiviert oder bearbeitet werden, während Du eine ihrer Spezialisierungen spielst."
L["This is a CDM Bar Layout string, not a profile string."] = "Dies ist ein CDM Leistenlayout String, kein Profil String."
L["This is an old CDM Bar Layout string. This format is no longer supported. Use the standard profile import instead."] = "Dies ist ein alter CDM Leistenlayout String. Dieses Format wird nicht mehr unterstützt. Nutze stattdessen den normalen Profilimport."
L["This module is excluded from Spec Overrides."] = "Dieses Modul ist von Spezialisierungs Überschreibungen ausgeschlossen."
L["This option can't be used while Blizzard Class Resource Art is enabled in Resource Bars."] = "Diese Option kann nicht genutzt werden, solange 'Blizzard Klassenressourcen Grafik' in den Ressourcenleisten aktiviert ist."
L["This option only affects Raid Buffs you can cast"] = "Diese Option betrifft nur Schlachtzugsbuffs, die Du wirken kannst"
L["This option only applies to the Badge style."] = "Diese Option gilt nur für den Abzeichen Stil."
L["This option only applies when Name > Target is selected."] = "Diese Option gilt nur, wenn 'Name > Ziel' ausgewählt ist."
L["This option only applies when Name > Target or Target is selected."] = "Diese Option gilt nur, wenn 'Name > Ziel' oder 'Ziel' ausgewählt ist."
L["This option only applies when Target is selected."] = "Diese Option gilt nur, wenn 'Ziel' ausgewählt ist."
L["This option only applies when the text shows a name."] = "Diese Option gilt nur, wenn der Text einen Namen zeigt."
L["This option requires a 2D Portrait or Class Art Style."] = "Erfordert ein 2D Porträt oder den Kunststil 'Klasse'."
L["This option requires a Border Size above 0"] = "Erfordert eine Rahmengröße über 0"
L["This option requires a Border Style other than Inherit (Main Frames)."] = "Erfordert einen anderen Rahmenstil als 'Vererben (Hauptfenster)'."
L["This option requires a Border Style other than Solid."] = "Erfordert einen anderen Rahmenstil als 'Einfarbig'."
L["This option requires a border style with divider art and a Border Size above 0."] = "Erfordert einen Rahmenstil mit Trennliniengrafik und eine Rahmengröße über 0."
L["This option requires a Circle or Pixels Circle Shape."] = "Erfordert die Form 'Kreis' oder 'Pixelkreis'."
L["This option requires a Dispel Overlay, Color Custom Borders or Use Dispel Colors."] = "Erfordert eine Bannüberlagerung, 'Eigene Rahmen einfärben' oder 'Bannfarben verwenden'."
L["This option requires a Glow Style other than None"] = "Erfordert einen anderen Leuchtstil als 'Keiner'"
L["This option requires a visible Portrait and Show Icon."] = "Erfordert ein sichtbares Porträt und 'Symbol anzeigen'."
L["This option requires an attached Power Bar, a Border Size above 0 and a border style with seam art."] = "Erfordert eine angehängte Ressourcenleiste, eine Rahmengröße über 0 und einen Rahmenstil mit Nahtgrafik."
L["This option requires an EllesmereUI Target or Focus frame."] = "Erfordert ein EllesmereUI Ziel- oder Fokusfenster."
L["This option requires an Outer Ring other than None."] = "Erfordert einen anderen äußeren Ring als 'Keiner'."
L["This option requires Art Style to be set to Class"] = "Erfordert, dass der Kunststil auf 'Klasse' eingestellt ist"
L["This option requires Blizzard Style to be disabled"] = "Erfordert, dass der Blizzard Stil deaktiviert ist"
L["This option requires Custom Border Style, Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "Erfordert eigenen Rahmenstil, 'Symbol anzeigen' und 'Symbol zum Teil der Leiste machen' mit dem EllesmereUI Stil."
L["This option requires Dispel Type Borders to be enabled."] = "Erfordert, dass 'Rahmen nach Banntyp' aktiviert ist."
L["This option requires Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "Erfordert 'Symbol anzeigen' und 'Symbol zum Teil der Leiste machen' mit dem EllesmereUI Stil."
L["This option requires Show Icon and the EllesmereUI style."] = "Erfordert 'Symbol anzeigen' und den EllesmereUI Stil."
L["This option requires Show Icon beside the cast bar and the EllesmereUI style."] = "Erfordert 'Symbol anzeigen' neben der Zauberleiste und den EllesmereUI Stil."
L["This option requires Solid or a border style with divider art, and a Border Size above 0."] = "Erfordert 'Einfarbig' oder einen Rahmenstil mit Trennliniengrafik sowie eine Rahmengröße über 0."
L["This option requires the Class Art Style."] = "Erfordert den Kunststil 'Klasse'."
L["This option requires the Class Colored Shape Border and Dark Mode."] = "Erfordert den klassenfarbigen Formrahmen und den dunklen Modus."
L["This option requires the WoW Forever style."] = "Erfordert den WoW Forever Stil."
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "Dies überschreibt die Einstellungen dieses Profils dauerhaft mit der Überschreibung '%s': Ihre erfassten Einstellungen sowie ihre eigenen Freigabemodus- und Stärkungszauber Manager Layouts (sofern vorhanden) werden zur eigenen Grundlage des Profils für jede Spezialisierung. ALLE Spezialisierungs Überschreibungsgruppen dieses Profils werden danach gelöscht und das UI wird neu geladen. Bedingte Überschreibungen sind nicht betroffen."
L["This profile was created before the beta wipe and is no longer compatible. Please create a new export."] = "Dieses Profil wurde vor dem Beta-Wipe erstellt und ist nicht mehr kompatibel. Bitte erstelle einen neuen Export."
L["This profile was created with a newer version of EllesmereUI. Please update your addon."] = "Dieses Profil wurde mit einer neueren Version von EllesmereUI erstellt. Bitte aktualisiere Dein Addon."
