L["This will create a fully unique unlock mode for this conditional group. Changes made to your default unlock mode will no longer affect it."] = "Dies erstellt einen völlig eigenen Freigabemodus für diese bedingte Gruppe. Änderungen an Deinem Standard-Freigabemodus wirken sich nicht mehr darauf aus."
L["This will create a fully unique unlock mode for this override group. Changes made to your default unlock mode will no longer affect these specs."] = "Dies erstellt einen völlig eigenen Freigabemodus für diese Überschreibungsgruppe. Änderungen an Deinem Standard-Freigabemodus wirken sich nicht mehr auf diese Spezialisierungen aus."
