L["Wrath's native quest and achievement tracker with EUI styling, visibility rules, auto-accept/turn-in and a quest-item hotkey."] = "Wraths native Quest- und Erfolgsverfolgung mit EUI Stil, Sichtbarkeitsregeln, automatischem Annehmen/Abgeben und einer Questgegenstand-Taste."
L["XP & Reputation Text Size"] = "EP- & Ruf-Textgröße"
