L["|cff00ff00[EllesmereUI]|r UI scale reset. /reload to re-snapshot from your Blizzard scale."] = "|cff00ff00[EllesmereUI]|r UI-Skalierung zurückgesetzt. /reload, um sie erneut von Deiner Blizzard Skalierung zu übernehmen."
L["|cff00ff98EllesmereUI:|r Overrides intro reset. The announcement popup fires on your next /reload; the video guide fires on your next click of the overrides glyph."] = "|cff00ff98EllesmereUI:|r Überschreibungs-Einführung zurückgesetzt. Das Ankündigungsfenster erscheint beim nächsten /reload; die Videoanleitung beim nächsten Klick auf das Überschreibungssymbol."
L["|cff00ff98EllesmereUI:|r Video guides and tutorial tips reset. Badges are back; one-time popups will fire again."] = "|cff00ff98EllesmereUI:|r Videoanleitungen und Tutorial-Tipps zurückgesetzt. Abzeichen sind zurück; einmalige Popups erscheinen erneut."
L["|cff888888...and %d more|r"] = "|cff888888...und %d weitere|r"
L["|cffff6060[EllesmereUI]|r Cannot enter Unlock Mode during combat."] = "|cffff6060[EllesmereUI]|r Freigabemodus kann im Kampf nicht aktiviert werden."
L["|cffff6060[EllesmereUI]|r Spec changed: Unlock Mode closed, unsaved layout changes discarded."] = "|cffff6060[EllesmereUI]|r Spezialisierung gewechselt: Freigabemodus geschlossen, ungespeicherte Layoutänderungen verworfen."
L["A blank bar to build from scratch."] = "Eine leere Leiste, die du von Grund auf aufbaust."
L["A bright spark at the edge of the fill."] = "Ein heller Funke am Rand der Füllung."
L["A friendly focus wins over the tank. The focus is checked at the moment you press it, also in combat."] = "Ein freundlicher Fokus hat Vorrang vor dem Tank. Der Fokus wird beim Drücken geprüft, auch im Kampf."
L["A group member to use as the tank. Empty uses the raid Main Tank, then the Dungeon Finder tank role. Updates out of combat."] = "Ein Gruppenmitglied, das als Tank verwendet wird. Leer nutzt den Haupttank des Schlachtzugs, dann die Tankrolle des Dungeonbrowsers. Wird außerhalb des Kampfes aktualisiert."
L["A line at every 10% and a tick at every 5% across the bar."] = "Eine Linie bei jeweils 10 % und eine Markierung bei jeweils 5 % über die Leiste."
L["A raid control panel with ready check, pull timer and target markers. In a raid it only shows while you are the leader or an assistant, since none of its buttons work without that; in a party it always shows."] = "Ein Schlachtzugsbedienfeld mit Bereitschaftsabfrage, Pull-Timer und Zielmarkierungen. Im Schlachtzug wird es nur angezeigt, wenn du Anführer oder Assistent bist, da keine seiner Tasten ohne diese Rechte funktioniert; in einer Gruppe wird es immer angezeigt."
