L["Clears your focus when you click the focus frame this way. Works in combat, where the right-click menu cannot clear focus."] = "Entfernt deinen Fokus, wenn du so auf das Fokusfenster klickst. Funktioniert im Kampf, wo das Rechtsklickmenü den Fokus nicht entfernen kann."
