L["Compact Band puts markers, ready check and pull timer in one row you can resize in Unlock Mode. The other choices keep the window layouts."] = "Kompaktes Band legt Markierungen, Bereitschaftsabfrage und Pull-Timer in eine Reihe, deren Größe du im Freigabemodus ändern kannst. Die anderen Optionen behalten die Fensterlayouts bei."
L["Compact clock and FPS readout."] = "Kompakte Uhr- und FPS-Anzeige."
L["Completed quest XP shows ahead of the fill in green, incomplete quest XP after it in gold. Quests under collapsed quest log headers are not counted."] = "EP aus abgeschlossenen Quests erscheinen grün vor der Füllung, EP aus unvollständigen Quests golden danach. Quests unter eingeklappten Überschriften im Questlog werden nicht gezählt."
