L["Hide Until Usable: only shown while usable and off cooldown, such as Overpower or Victory Rush after a proc; low resources do not hide it. Hide Outside Form/Stance: only shown in the form or stance the spell needs, even on cooldown. Keep Place leaves the gap; the others close it."] = "Bis benutzbar ausblenden: nur angezeigt, solange benutzbar und nicht in Abklingzeit, etwa Überwältigen oder Siegesrausch nach einem Proc; zu wenig Ressourcen blendet es nicht aus. Außerhalb von Gestalt/Haltung ausblenden: nur in der Gestalt oder Haltung angezeigt, die der Zauber benötigt, auch während der Abklingzeit. Platz behalten lässt die Lücke; die anderen schließen sie."
