L["Hovering a stat in the sidebar glows the equipped items that give it (Hit, Crit, Haste, Defense, Strength...)."] = "Beim Überfahren eines Werts in der Seitenleiste leuchten die angelegten Gegenstände, die ihn gewähren (Trefferwertung, Kritisch, Tempo, Verteidigung, Stärke...)."
