L["Quest XP Overlay"] = "Quest-EP-Überlagerung"
L["Raid Debuffs Filter"] = "Filter für Schlachtzug Schwächungszauber"
L["Raid Debuffs shows the common raid debuffs (armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements, Hunter's Mark) from anyone."] = "Schlachtzug Schwächungszauber zeigt die üblichen Schlachtzug-Schwächungszauber (Rüstung, erlittener Zauber- und körperlicher Schaden, erlittene kritische Treffer, Angriffskraft, Angriffs- und Zaubertempo, erhaltene Heilung, Richturteile, Mal des Jägers) von allen an."
L["Reads the item's own stats; enchants and gems are not counted."] = "Liest die eigenen Werte des Gegenstands; Verzauberungen und Edelsteine werden nicht gezählt."
L["Reload to finish resetting EUI."] = "Neu laden, um das Zurücksetzen von EUI abzuschließen."
L["Reload to finish uninstalling EUI."] = "Neu laden, um die Deinstallation von EUI abzuschließen."
L["Rename DataBar"] = "Datenleiste umbenennen"
L["Rested After Quest XP"] = "Erholt nach Quest-EP"
L["Rested color"] = "Erholungsfarbe"
L["Return every EUI addon to its defaults."] = "Setzt jedes EUI Addon auf seine Standardwerte zurück."
L["Revert EUI's changes and disable."] = "Macht die Änderungen von EUI rückgängig und deaktiviert es."
L["Right Endcap"] = "Rechte Endkappe"
L["Scroll Distance"] = "Scrollweite"
L["Second Timer"] = "Zweiter Timer"
L["Secondary Spec"] = "Sekundäre Spezialisierung"
L["Selection Color"] = "Auswahlfarbe"
L["Selection Color: Custom Color"] = "Auswahlfarbe: Eigene Farbe"
L["SELF COMBAT TEXT"] = "EIGENER KAMPFTEXT"
L["Self Combat Text"] = "Eigener Kampftext"
L["Sell Junk skips items with no vendor price, equipment set gear and pinned items."] = "Müll verkaufen überspringt Gegenstände ohne Händlerpreis, Gegenstände aus Ausrüstungssets und angeheftete Gegenstände."
L["Shaped"] = "Geformt"
L["Shaped Cooldown Swipe"] = "Geformte Abklingzeit-Wischtextur"
L["Share Keybind With"] = "Tastenbelegung teilen mit"
L["Shift + Click World Markers"] = "Umschalt + Klick Weltmarker"
L["Shift + Left Click a marker icon to use its world marker item, then click the ground. Only markers whose item is in your bags get it; the rest keep Shift + Click to clear the target marker. Shift + Left Click the clear icon presses the server's Reset Markers button."] = "Umschalt + Linksklick auf ein Markierungssymbol benutzt dessen Weltmarker-Gegenstand, dann auf den Boden klicken. Nur Markierungen, deren Gegenstand in deinen Taschen ist, erhalten dies; die übrigen behalten Umschalt + Klick zum Entfernen der Zielmarkierung. Umschalt + Linksklick auf das Entfernen-Symbol drückt die Taste Markierungen zurücksetzen des Servers."
L["Show a small coin in the corner of items marked as junk."] = "Zeigt eine kleine Münze in der Ecke von als Müll markierten Gegenständen."
L["Show at Max Level"] = "Auf Höchststufe anzeigen"
L["Show Coin on Junk"] = "Münze bei Müll anzeigen"
L["Show Convert to Raid"] = "In Schlachtzug umwandeln anzeigen"
L["Show Dividers"] = "Trennlinien anzeigen"
L["Show Equipped Item Color"] = "Farbe angelegter Gegenstände anzeigen"
L["Show Inspect Enchant Names Instead of Icons"] = "Verzauberungsnamen statt Symbolen beim Betrachten anzeigen"
L["Show Item Icon Name"] = "Gegenstandssymbolnamen anzeigen"
L["Show Item ID on Tooltip"] = "Gegenstands-ID im Tooltip anzeigen"
L["Show Player Buffs"] = "Stärkungszauber des Spielers anzeigen"
L["Show Reinvite"] = "Neu einladen anzeigen"
L["Show Rested XP"] = "Erholte EP anzeigen"
L["Show Target Name"] = "Zielnamen anzeigen"
L["Show the coin button in the bag header. Click it, then click items to mark or unmark them as junk. Junk goes into its own Junk category, and a Sell Junk button appears next to the coin while a merchant is open."] = "Zeigt die Münztaste in der Taschenkopfzeile. Klicke darauf und dann auf Gegenstände, um sie als Müll zu markieren oder die Markierung aufzuheben. Müll kommt in eine eigene Kategorie Müll, und neben der Münze erscheint eine Taste Müll verkaufen, solange ein Händler geöffnet ist."
L["Shown at max level. Profession bonuses are only checked on your own sheet."] = "Wird auf Höchststufe angezeigt. Berufsboni werden nur in deinem eigenen Charakterfenster geprüft."
L["Shows the common raid debuffs from anyone: armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements and Hunter's Mark."] = "Zeigt die üblichen Schlachtzug-Schwächungszauber von allen an: Rüstung, erlittener Zauber- und körperlicher Schaden, erlittene kritische Treffer, Angriffskraft, Angriffs- und Zaubertempo, erhaltene Heilung, Richturteile und Mal des Jägers."
L["Shows the Convert to Raid button. In a raid of five or fewer it reads Convert to Party: everyone is removed and invited back to a new party."] = "Zeigt die Taste In Schlachtzug umwandeln. In einem Schlachtzug mit fünf oder weniger Spielern lautet sie In Gruppe umwandeln: alle werden entfernt und erneut in eine neue Gruppe eingeladen."
L["Shows the debuffs you apply plus the common raid debuffs from anyone."] = "Zeigt die von dir gewirkten Schwächungszauber sowie die üblichen Schlachtzug-Schwächungszauber von allen."
L["Shows the Disband button. It always asks before disbanding, but hiding it puts it out of misclick range for good."] = "Zeigt die Taste Auflösen. Sie fragt vor dem Auflösen immer nach, aber durch das Ausblenden ist sie dauerhaft außer Reichweite von Fehlklicks."
L["Shows the hovered player's buffs as icons next to the tooltip (up to 16)."] = "Zeigt die Stärkungszauber des überfahrenen Spielers als Symbole neben dem Tooltip (bis zu 16)."
L["Shows the overlay, type icon and border colors only for debuffs you can currently dispel."] = "Zeigt Überlagerung, Typsymbol und Rahmenfarben nur für Schwächungszauber, die du gerade bannen kannst."
L["Shows the Reinvite button. It asks first, then removes everyone and invites them back to the same kind of group. Players have to accept the new invite."] = "Zeigt die Taste Neu einladen. Sie fragt zuerst nach, entfernt dann alle und lädt sie erneut in dieselbe Gruppenart ein. Die Spieler müssen die neue Einladung annehmen."
L["Shows your damage taken, healing, avoids and combat enter/leave above the player frame instead of Blizzard's combat text, whose other messages are hidden while this is on. Move it in Unlock Mode."] = "Zeigt erlittenen Schaden, Heilung, Vermeidungen sowie Kampfbeginn/-ende über dem Spielerfenster statt des Blizzard-Kampftexts an, dessen andere Meldungen ausgeblendet sind, solange dies aktiv ist. Im Freigabemodus verschieben."
L["Smart Ticks"] = "Intelligente Markierungen"
L["Spell IDs in the Breakdown"] = "Zauber-IDs in der Aufschlüsselung"
L["Stagger Hits"] = "Treffer staffeln"
L["Stat Hover Highlight"] = "Hervorhebung beim Überfahren von Werten"
L["Static"] = "Statisch"
L["Straight"] = "Gerade"
L["Style Page Look Menus"] = "Menüs im Aussehen der Stilseite"
L["Swipe Color"] = "Wischfarbe"
L["Swipe Style"] = "Wischstil"
L["Tank Name"] = "Tankname"
L["Text Shadow"] = "Textschatten"
L["The [Merfin] Experience Bar (Luxthos) WeakAura: blue to purple gradient, Quest XP Overlay, spark, rested after quest XP and seven texts with level, times and time to level."] = "Die [Merfin] Experience Bar (Luxthos) WeakAura: Farbverlauf von Blau zu Lila, Quest-EP-Überlagerung, Funke, Erholt nach Quest-EP und sieben Texte mit Stufe, Zeiten und Zeit bis zum Stufenaufstieg."
L["The classic tooltip box around the meter window, with vanilla header buttons and every EllesmereUI meter feature."] = "Der klassische Tooltip-Rahmen um das Meterfenster, mit Vanilla-Kopfzeilentasten und jeder EllesmereUI Meterfunktion."
L["The gap between a nested menu's icons and the entry that opens it."] = "Der Abstand zwischen den Symbolen eines verschachtelten Menüs und dem Eintrag, der es öffnet."
L["The rested segment starts where the Quest XP Overlay ends instead of at your current XP."] = "Der Erholt-Abschnitt beginnt dort, wo die Quest-EP-Überlagerung endet, statt bei deinen aktuellen EP."
L["The talent group this action menu works in. Outside it the keybind does nothing and the menu is hidden where it is nested."] = "Die Talentgruppe, in der dieses Aktionsmenü funktioniert. Außerhalb davon bewirkt die Tastenbelegung nichts, und das Menü ist dort ausgeblendet, wo es verschachtelt ist."
L["Third Timer"] = "Dritter Timer"
L["This option requires an EllesmereUI Focus frame."] = "Diese Option benötigt ein EllesmereUI Fokusfenster."
L["This option requires XP Bar Style EllesmereUI or Luxthos"] = "Diese Option benötigt den EP-Leistenstil EllesmereUI oder Luxthos"
L["Time This Session and XP per Hour carry on through a /reload (a load within five minutes) instead of starting over."] = "Zeit dieser Sitzung und EP pro Stunde laufen über ein /reload (ein Laden innerhalb von fünf Minuten) weiter, statt neu zu beginnen."
L["Timed Buffs"] = "Zeitlich begrenzte Stärkungszauber"
L["Toggle Raid Tools"] = "Schlachtzugswerkzeuge umschalten"
L["Toggles the Raid Tools panels, in or out of combat.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "Schaltet die Schlachtzugswerkzeuge-Felder um, im oder außerhalb des Kampfes.\n\nLinksklick, um eine Tastenbelegung festzulegen.\nRechtsklick, um die Belegung aufzuheben."
L["Two Windows"] = "Zwei Fenster"
L["Uninstall & Reload"] = "Deinstallieren & neu laden"
L["Uninstall EUI"] = "EUI deinstallieren"
L["Up Left"] = "Oben links"
L["Up Right"] = "Oben rechts"
L["Use another action menu's keybind while that menu is not loaded. Both menus must be assigned to different specs."] = "Nutzt die Tastenbelegung eines anderen Aktionsmenüs, solange dieses Menü nicht geladen ist. Beide Menüs müssen unterschiedlichen Spezialisierungen zugewiesen sein."
L["Which buffs enemy nameplates show. Fine-tune it on the Aura Filters page."] = "Welche Stärkungszauber gegnerische Namensplaketten zeigen. Feinabstimmung auf der Seite Aurenfilter."
L["Which ends of the bar show the gryphons."] = "An welchen Enden der Leiste die Greifen angezeigt werden."
L["XP Bar Style"] = "EP-Leistenstil"
L["XP color"] = "EP-Farbe"
L["Every module runs on native Wrath APIs. Retail looks and settings were ported wherever the 3.3.5a client supports them, and Retail-only systems were left out. Notes are grouped by module, newest first, and each header shows that module's backport version."] = "Jedes Modul läuft auf nativen Wrath-APIs. Retail-Aussehen und -Einstellungen wurden überall portiert, wo der 3.3.5a-Client sie unterstützt, und reine Retail-Systeme wurden weggelassen. Die Notizen sind nach Modul gruppiert, neueste zuerst, und jede Überschrift zeigt die Backport-Version des Moduls."
L["Icons beside each enemy for every crowd control category they are under or recovering from: green means the next one lasts half as long, yellow a quarter, red immune. A timer shows the 18 second reset."] = "Symbole neben jedem Gegner für jede Kategorie von Kontrolleffekten, unter denen er steht oder von denen er sich erholt: grün bedeutet, der nächste hält halb so lange, gelb ein Viertel, rot immun. Ein Timer zeigt das Zurücksetzen nach 18 Sekunden."
L["A health bar for each enemy pet under its owner's frame. Left-click targets the pet, right-click sets focus."] = "Eine Gesundheitsleiste für jeden gegnerischen Begleiter unter dem Fenster seines Besitzers. Linksklick wählt den Begleiter als Ziel, Rechtsklick setzt den Fokus."
L["Enemy frames for arena1-5 with class colored health, power and cast bars plus a highlight on your target. Left-click targets, right-click sets focus. There is no Retail equivalent."] = "Gegnerfenster für arena1-5 mit Gesundheits-, Ressourcen- und Zauberleisten in Klassenfarbe sowie einer Hervorhebung deines Ziels. Linksklick wählt als Ziel, Rechtsklick setzt den Fokus. Es gibt kein Retail-Gegenstück."
L["The class icon swaps to the highest priority crowd control or immunity with a spiral and timer, and the PvP trinket icon tracks its 2 minute cooldown from the combat log."] = "Das Klassensymbol wechselt zum Kontrolleffekt oder zur Immunität mit der höchsten Priorität, mit Spirale und Timer, und das PvP-Schmuckstücksymbol verfolgt seine Abklingzeit von 2 Minuten aus dem Kampflog."
L["Bar Texture lists textures from SharedMedia and other addons using LibSharedMedia"] = "Leistentextur listet Texturen aus SharedMedia und anderen Addons auf, die LibSharedMedia verwenden"
L["Enemies beyond your class's 30-40 yard spell range fade to a chosen opacity"] = "Gegner außerhalb der Zauberreichweite deiner Klasse von 30-40 Metern verblassen auf eine gewählte Deckkraft"
L["Preview 2 to 5 sample frames in Unlock Mode, while the options page is open, or with /earena test"] = "Vorschau von 2 bis 5 Beispielfenstern im Freigabemodus, während die Optionsseite geöffnet ist, oder mit /earena test"
L["Frames stay up while an enemy is stealthed or out of sight, dimmed and marked Unseen"] = "Fenster bleiben sichtbar, während ein Gegner verstohlen oder außer Sicht ist, abgedunkelt und als Ungesehen markiert"
L["Optionally hides Blizzard's arena frames while these are in use"] = "Blendet optional die Arenafenster von Blizzard aus, solange diese verwendet werden"
L["The Debuff Filter gets Raid Debuffs and Own and Raid Debuffs, with the same raid debuff list as the Unit Frames."] = "Der Schwächungszauber Filter erhält Schlachtzug Schwächungszauber sowie Eigene und Schlachtzug Schwächungszauber, mit derselben Liste von Schlachtzug-Schwächungszaubern wie die Einheitenfenster."
L["Choose which buffs enemy nameplates show: Timed Buffs, Only Dispellable or Show All, which shows every buff."] = "Wähle, welche Stärkungszauber gegnerische Namensplaketten zeigen: Zeitlich begrenzte Stärkungszauber, Nur bannbare oder Alle anzeigen, das jeden Stärkungszauber zeigt."
L["Every nameplate text has an Outline choice under its Size: None, Outline, Thick Outline or Shadow, or keep the module default. Covers names, level, health, Target of Target, cast texts, aura text and friendly names."] = "Jeder Namensplakettentext hat unter seiner Größe eine Konturauswahl: Keine, Kontur, Dicke Kontur oder Schatten, oder der Modulstandard bleibt. Betrifft Namen, Stufe, Gesundheit, Ziel des Ziels, Zaubertexte, Aurentext und freundliche Namen."
L["Cast bars now fill every frame instead of stepping with each nameplate refresh. The spark and timer move smoothly too, and the extra work stops when no cast is visible."] = "Zauberleisten füllen sich jetzt in jedem Frame, statt mit jeder Aktualisierung der Namensplakette zu springen. Funke und Timer bewegen sich ebenfalls flüssig, und die zusätzliche Arbeit stoppt, wenn kein Zauber sichtbar ist."
L["Core Text Positions offers all Retail texts: Enemy Name, Level | Name, Target of Target, Health % and Health # with their combined variants. Each text's cog sets its size."] = "Kerntextpositionen bietet alle Retail-Texte: Gegnername, Stufe | Name, Ziel des Ziels, Gesundheit % und Gesundheit # mit ihren kombinierten Varianten. Das Zahnrad jedes Texts legt seine Größe fest."
L["Health and cast bars offer the EllesmereUI textures (Melli, Atrocity, Fade, Matte and more), as on Retail"] = "Gesundheits- und Zauberleisten bieten die EllesmereUI Texturen (Melli, Atrocity, Fade, Matte und mehr), wie auf Retail"
L["Health and cast bar textures include textures from SharedMedia and other addons"] = "Gesundheits- und Zauberleistentexturen enthalten Texturen aus SharedMedia und anderen Addons"
L["Display and Colors show a live preview plate; click any part of it to jump to its setting"] = "Anzeige und Farben zeigen eine Live-Vorschauplakette; klicke auf einen beliebigen Teil, um zu seiner Einstellung zu springen"
L["Retail bar size, colors, threat modes, cast colors, target arrows and Execute Pulse Glow"] = "Retail-Leistengröße, Farben, Bedrohungsmodi, Zauberfarben, Zielpfeile und Hinrichten Pulsieren"
L["Each slot holds one element; auras, raid marker and classification can also sit below the cast bar"] = "Jeder Platz enthält ein Element; Auren, Schlachtzugsmarkierung und Klassifizierung können auch unter der Zauberleiste sitzen"
L["Health # uses Blizzard style abbreviations (1.2K, 12K, 1.2M) with an optional % decimal"] = "Gesundheit # nutzt Abkürzungen im Blizzard-Stil (1.2K, 12K, 1.2M) mit optionaler % Dezimalstelle"
L["A profile imported from Retail no longer blows the target nameplate up to fill the screen."] = "Ein aus Retail importiertes Profil bläst die Namensplakette des Ziels nicht mehr bildschirmfüllend auf."
L["Border None now hides only the borders, not the cast bar text, timer, shield and kick mark."] = "Rahmen Keine blendet jetzt nur die Rahmen aus, nicht den Zauberleistentext, Timer, Schild und die Unterbrechungsmarkierung."
L["The options preview plate no longer disappears after switching tabs or closing the panel."] = "Die Vorschauplakette in den Optionen verschwindet nicht mehr nach dem Wechseln der Reiter oder dem Schließen des Fensters."
L["The Interrupt on CD cast color now shows while your interrupt recharges, as on Retail, instead of the reverse."] = "Die Zauberfarbe Unterbrechungszauber auf Abklingzeit wird jetzt angezeigt, während sich dein Unterbrechungszauber auflädt, wie auf Retail, statt umgekehrt."
L["Raid and party names each get their own outline: None, Outline, Thick Outline, Shadow, or the Raid Frames font default."] = "Schlachtzugs- und Gruppennamen erhalten jeweils eine eigene Kontur: Keine, Kontur, Dicke Kontur, Schatten oder der Schriftstandard der Schlachtzugsfenster."
L["A new Group Layout stacks two raid groups per column, then starts the next column to the right, so a 20-player raid forms a 2x2 block."] = "Ein neues Gruppenlayout stapelt zwei Schlachtzugsgruppen pro Spalte und beginnt dann die nächste Spalte rechts davon, sodass ein Schlachtzug mit 20 Spielern einen 2x2-Block bildet."
L["Ready check icons appear above debuffs and keep each player result for ten seconds after the check finishes."] = "Symbole der Bereitschaftsabfrage erscheinen über den Schwächungszaubern und behalten das Ergebnis jedes Spielers zehn Sekunden nach Ende der Abfrage."
L["The debuff displayed in the central Raid Debuff icon is excluded from the regular debuff bar, leaving room for other debuffs."] = "Der im zentralen Schlachtzug-Schwächungszaubersymbol angezeigte Schwächungszauber wird aus der normalen Schwächungszauberleiste ausgeschlossen und schafft Platz für andere Schwächungszauber."
L["Raid and party frames dim outside range on Wrath, including in combat. Dim Out of Range and Out of Range Alpha control the fade."] = "Schlachtzugs- und Gruppenfenster werden auf Wrath außer Reichweite abgedunkelt, auch im Kampf. Außer Reichweite abdunkeln und Transparenz außer Reichweite steuern das Verblassen."
L["A large icon in the middle of each frame for important ICC, Ruby Sanctum, Trial of the Crusader, Ulduar and Naxxramas debuffs, highest priority first, with timer, stacks and a dispel colored border. Without a listed debuff it can show a dispellable one instead."] = "Ein großes Symbol in der Mitte jedes Fensters für wichtige Schwächungszauber in ICC, Rubinsanktum, Prüfung des Kreuzfahrers, Ulduar und Naxxramas, höchste Priorität zuerst, mit Timer, Stapeln und einem Rahmen in Bannfarbe. Ohne gelisteten Schwächungszauber kann es stattdessen einen bannbaren zeigen."
L["Dispel Overlay styles with opacity, a dispel colored Frame Border, Type Icon Position, per-type Dispel Colors and Only Show Dispellable."] = "Stile der Bannüberlagerung mit Deckkraft, ein Fensterrahmen in Bannfarbe, Position des Typ Symbols, Bannfarben pro Typ und Nur bannbare anzeigen."
L["Overlay, Real or No Preview. The preview opens while the Raid or Party page is open and closes when you leave it, close the panel or enter combat."] = "Überlagerung, Echt oder Keine Vorschau. Die Vorschau öffnet sich, während die Schlachtzugs- oder Gruppenseite geöffnet ist, und schließt sich, wenn du sie verlässt, das Fenster schließt oder in den Kampf gehst."
L["Enemy casts show as icons on the party or raid member being cast at, with a cast sweep and interruptible border. Party defaults to When Healing; each raid layout has its own mode. Wrath has no spell target, so the victim is the caster's target, and only enemies someone in the group targets are seen"] = "Gegnerische Zauber erscheinen als Symbole auf dem Gruppen- oder Schlachtzugsmitglied, auf das gezaubert wird, mit Zauber-Wischtextur und Rahmen für unterbrechbare Zauber. Gruppe ist standardmäßig auf Beim Heilen; jedes Schlachtzugslayout hat einen eigenen Modus. Wrath kennt kein Zauberziel, daher ist das Opfer das Ziel des Zaubernden, und es werden nur Gegner erkannt, die jemand in der Gruppe als Ziel hat"
L["Damage shields show on the health bar as on Retail: Absorb Style, Opacity, Color, Placement and Show Overshield. Wrath does not report shield amounts, so they are estimated from the combat log"] = "Schadensschilde erscheinen auf der Gesundheitsleiste wie auf Retail: Absorptions Stil, Deckkraft, Farbe, Platzierung und Überhangschild anzeigen. Wrath meldet keine Schildwerte, daher werden sie aus dem Kampflog geschätzt"
L["Health Bar Texture lists textures from SharedMedia and other addons, also in the aura indicator preview"] = "Gesundheitsleistentextur listet Texturen aus SharedMedia und anderen Addons auf, auch in der Vorschau der Aurenindikatoren"
L["25-Player Preview"] = "Vorschau für 25 Spieler"
L["The Unlock Mode and options previews open on the 25-player layout instead of 40"] = "Die Vorschauen im Freigabemodus und in den Optionen öffnen sich im Layout für 25 Spieler statt 40"
L["Health color modes, backgrounds, threat, target and hover borders, text and icon placement"] = "Gesundheitsfarbmodi, Hintergründe, Bedrohung, Ziel- und Mouseover-Rahmen, Text- und Symbolplatzierung"
L["Incoming heals and resurrections from players who use a HealComm addon"] = "Eingehende Heilungen und Wiederbelebungen von Spielern, die ein HealComm-Addon verwenden"
L["Main Tank, Pet and Friendly Boss frames plus Healer Mana text, each with an Unlock Mode mover"] = "Haupttank-, Begleiter- und freundliche Bossfenster sowie Heilermana-Text, jeweils mit einem Mover im Freigabemodus"
L["The Party page has a LAYOUT section with Horizontal Frames"] = "Die Gruppenseite hat einen Bereich LAYOUT mit Horizontale Fenster"
L["Ready check icons show a green check for players who accepted and for the one who started the check, instead of a red X when the check ended."] = "Symbole der Bereitschaftsabfrage zeigen einen grünen Haken für Spieler, die zugestimmt haben, und für den, der die Abfrage gestartet hat, statt eines roten X am Ende der Abfrage."
L["The party leader icon shows on the leader only instead of on several party members."] = "Das Symbol des Gruppenanführers erscheint nur beim Anführer statt bei mehreren Gruppenmitgliedern."
L["Set Focus and Clear Focus in the raid and party frame menu work out of combat without the 'blocked from an action' popup; in combat they are hidden, use a Click Casting Focus binding there."] = "Fokus setzen und Fokus entfernen im Menü der Schlachtzugs- und Gruppenfenster funktionieren außerhalb des Kampfes ohne das Popup 'von einer Aktion blockiert'; im Kampf sind sie ausgeblendet, nutze dort eine Klickzauber-Belegung für den Fokus."
L["Ready check icons show on raid and party frames again."] = "Symbole der Bereitschaftsabfrage erscheinen wieder auf Schlachtzugs- und Gruppenfenstern."
L["Hide Sated / Exhaustion also hides the 81005 Bloodlust lockout debuff."] = "Gesättigt / Erschöpfung ausblenden blendet auch den Kampfrausch-Sperrschwächungszauber 81005 aus."
L["Pet frames no longer throw a SecureTemplates strupper error when they first appear."] = "Begleiterfenster werfen beim ersten Erscheinen keinen SecureTemplates strupper Fehler mehr."
L["The Buffs/Debuffs editor's Add New menu no longer closes on the first click."] = "Das Menü Neu hinzufügen im Stärkungs-/Schwächungszauber-Editor schließt sich nicht mehr beim ersten Klick."
L["Element Options for raid and party frames now open the matching settings."] = "Element Optionen für Schlachtzugs- und Gruppenfenster öffnen jetzt die passenden Einstellungen."
L["Profile strings exported from Retail EllesmereUI import everything this client supports: each module keeps its current settings and takes the Retail values it understands. Retail-only modules, spec setups and Cooldown Manager spells are skipped, and chat reports how many settings came in."] = "Aus Retail EllesmereUI exportierte Profilstrings importieren alles, was dieser Client unterstützt: jedes Modul behält seine aktuellen Einstellungen und übernimmt die Retail-Werte, die es versteht. Reine Retail-Module, Spezialisierungs-Setups und Zauber des Abklingzeiten Managers werden übersprungen, und der Chat meldet, wie viele Einstellungen übernommen wurden."
L["A button on Global Settings puts back the game settings EUI changed (nameplate, minimap, chat and tooltip options, chat font sizes and keys Quickdraw took), then turns EUI off for this character and reloads. Your profiles are kept."] = "Eine Taste in den Globalen Einstellungen stellt die Spieleinstellungen wieder her, die EUI geändert hat (Namensplaketten-, Minikarten-, Chat- und Tooltipoptionen, Chat-Schriftgrößen und von Schnellzugriff belegte Tasten), schaltet EUI dann für diesen Charakter ab und lädt neu. Deine Profile bleiben erhalten."
L["A drawn cooldown sweep for modules that want round or colored swipes; the Wrath client's own swipe is always a dark square. Cooldown Manager uses it first."] = "Eine gezeichnete Abklingzeit-Wischtextur für Module, die runde oder farbige Wischtexturen wollen; die eigene Wischtextur des Wrath-Clients ist immer ein dunkles Quadrat. Der Abklingzeiten Manager nutzt sie zuerst."
L["When a guild or group member runs a newer EllesmereUI release, chat tells you once per session. Type /euiupdate for the download link. Wrath has no internet access, so the news comes from other EUI users."] = "Wenn ein Gilden- oder Gruppenmitglied eine neuere EllesmereUI-Version nutzt, sagt dir der Chat das einmal pro Sitzung. Gib /euiupdate ein für den Downloadlink. Wrath hat keinen Internetzugang, daher kommt die Nachricht von anderen EUI-Nutzern."
L["The Locales addon provides community translations for all original Wrath client languages, with English fallback and Lua 5.1 formatting."] = "Das Locales-Addon bietet Übersetzungen der Community für alle ursprünglichen Sprachen des Wrath-Clients, mit englischem Fallback und Lua 5.1-Formatierung."
L["The collapsed menu displays the original Ellesmere E logo with the UI accent color and a working close icon on the Wrath client."] = "Das eingeklappte Menü zeigt das originale Ellesmere-E-Logo in der Akzentfarbe des UI und ein funktionierendes Schließen-Symbol auf dem Wrath-Client."
L["Fonts, bar textures and sounds that other addons register with LibSharedMedia appear in the EllesmereUI menus, including ones registered after login."] = "Schriftarten, Leistentexturen und Sounds, die andere Addons bei LibSharedMedia registrieren, erscheinen in den EllesmereUI-Menüs, auch solche, die nach dem Einloggen registriert werden."
L["A shared outline picker for individual texts: None, Outline, Thick Outline or Shadow, with Module Default following the Fonts page. Text keeps its color when you switch."] = "Eine gemeinsame Konturauswahl für einzelne Texte: Keine, Kontur, Dicke Kontur oder Schatten, wobei Modulstandard der Seite Schriftarten folgt. Der Text behält beim Wechseln seine Farbe."
L["The Incompatible Addon popup can disable the other addon or the affected EllesmereUI module and reload. Okay and Don't show again work as before."] = "Das Popup für inkompatible Addons kann das andere Addon oder das betroffene EllesmereUI-Modul deaktivieren und neu laden. OK und Nicht mehr anzeigen funktionieren wie bisher."
L["Per-spec setting groups with automatic capture and their own Unlock Mode layouts, plus conditional overrides for dungeons, raids, arenas, battlegrounds, solo play and out of combat."] = "Einstellungsgruppen pro Spezialisierung mit automatischer Erfassung und eigenen Layouts im Freigabemodus, dazu bedingte Überschreibungen für Dungeons, Schlachtzüge, Arenen, Schlachtfelder, Solospiel und außerhalb des Kampfes."
L["The Esc menu has EllesmereUI and EUI Unlock Mode buttons, shown by default. Both follow the EUI Buttons setting in Global Settings."] = "Das Esc-Menü hat die Tasten EllesmereUI und EUI-Freigabemodus, standardmäßig angezeigt. Beide folgen der Einstellung EUI Tasten in den Globalen Einstellungen."
L["With Show Spell ID on Tooltip on, item tooltips add the item ID and icon file name. Each line has its own toggle"] = "Mit aktivem Zauber-ID im Tooltip anzeigen zeigen Gegenstandstooltips die Gegenstands-ID und den Dateinamen des Symbols. Jede Zeile hat einen eigenen Schalter"
L["Raid and Unit Frames read absorb shields from a shared estimate: rank base value plus your own spell power, minus what each shield absorbs in the combat log. Clients with a native absorb API use it directly"] = "Schlachtzugs- und Einheitenfenster lesen Absorptionsschilde aus einer gemeinsamen Schätzung: Grundwert des Rangs plus deine eigene Zaubermacht, abzüglich dessen, was jedes Schild laut Kampflog absorbiert. Clients mit nativer Absorptions-API nutzen diese direkt"
L["Arena Frames joins the sidebar, first-use list, profiles, spec overrides, module fonts and search"] = "Arenafenster kommt in die Seitenleiste, die Liste für die erste Nutzung, Profile, Spezialisierungs Überschreibungen, Modulschriftarten und die Suche"
L["Profile strings and shared exports work again"] = "Profilstrings und geteilte Exporte funktionieren wieder"
L["An ice blue options theme; Match Accent to Theme follows each theme's palette"] = "Ein eisblaues Optionsthema; Akzent an Thema anpassen folgt der Palette jedes Themas"
L["Lights, beams, music and spin on boss kills, arena and battleground wins, Bloodlust/Heroism and level ups"] = "Lichter, Strahlen, Musik und Drehung bei Bosskills, Arena- und Schlachtfeldsiegen, Kampfrausch/Heldentum und Stufenaufstiegen"
L["Show Spell ID on Tooltip covers spells, action buttons, auras and chat links (off by default)"] = "Zauber-ID im Tooltip anzeigen deckt Zauber, Aktionstasten, Auren und Chatlinks ab (standardmäßig aus)"
L["The options sidebar shows the combined memory used by all loaded EllesmereUI addons"] = "Die Seitenleiste der Optionen zeigt den gesamten Speicherverbrauch aller geladenen EllesmereUI-Addons"
L["The sidebar sync button opens its profile list again instead of erroring when you have more than one profile."] = "Die Synchronisationstaste der Seitenleiste öffnet wieder ihre Profilliste, statt einen Fehler zu werfen, wenn du mehr als ein Profil hast."
L["Retail profile strings bring their element positions: action, XP and menu bars, CDM bars, raid and party frames, chat, damage meter windows, QoL displays, resource bars and the fixed tooltip land where the creator placed them."] = "Retail-Profilstrings bringen ihre Elementpositionen mit: Aktions-, EP- und Menüleisten, CDM-Leisten, Schlachtzugs- und Gruppenfenster, Chat, Schadensmeterfenster, Komfortfunktionsanzeigen, Ressourcenleisten und der feste Tooltip landen dort, wo der Ersteller sie platziert hat."
L["Nameplates-only Retail profile strings are recognised as Retail; bar width and height, cast bar height and color, name size and aura sizes carry over."] = "Retail-Profilstrings nur für Namensplaketten werden als Retail erkannt; Leistenbreite und -höhe, Zauberleistenhöhe und -farbe, Namensgröße und Aurengrößen werden übernommen."
L["Unlock Mode: the top bar toggle icons and labels are brighter, so they no longer read dark grey on the banner."] = "Freigabemodus: Die Umschaltsymbole und Beschriftungen der oberen Leiste sind heller, sodass sie auf dem Banner nicht mehr dunkelgrau wirken."
L["Set Focus and Clear Focus in right-click menus from EUI frames go through a secure button out of combat instead of being blocked; in combat they are hidden."] = "Fokus setzen und Fokus entfernen in Rechtsklickmenüs von EUI-Fenstern laufen außerhalb des Kampfes über eine sichere Taste, statt blockiert zu werden; im Kampf sind sie ausgeblendet."
L["Unlock Mode: the arrow keys move the selected element 1 pixel again (hold Shift for 100)."] = "Freigabemodus: Die Pfeiltasten bewegen das ausgewählte Element wieder um 1 Pixel (Umschalt halten für 100)."
L["Works alongside !!!ClassicAPI: its clipping and mask functions are no longer used on EUI frames, so animated glows and the options panel stop erroring."] = "Funktioniert zusammen mit !!!ClassicAPI: dessen Clipping- und Maskenfunktionen werden auf EUI-Fenstern nicht mehr verwendet, sodass animierte Leuchteffekte und das Optionsfenster keine Fehler mehr werfen."
L["Opening the options no longer errors with \"attempt to index local 'mask'\" on clients where another addon adds an empty mask function."] = "Das Öffnen der Optionen wirft keinen Fehler \"attempt to index local 'mask'\" mehr auf Clients, bei denen ein anderes Addon eine leere Maskenfunktion hinzufügt."
L["The profile Import and Export boxes no longer error with \"attempt to call method 'GetNumLines'\" and scroll to fit long strings."] = "Die Felder für Profil-Import und -Export werfen keinen Fehler \"attempt to call method 'GetNumLines'\" mehr und scrollen, um lange Strings aufzunehmen."
L["The collapsed menu shows the Ellesmere E logo again instead of a plain black circle."] = "Das eingeklappte Menü zeigt wieder das Ellesmere-E-Logo statt eines einfachen schwarzen Kreises."
L["Action button tooltips show the real spell ID instead of the spellbook slot."] = "Tooltips von Aktionstasten zeigen die echte Zauber-ID statt des Zauberbuchplatzes."
L["Fixed an \"attempt to call global 'issecretvalue'\" error from Cooldown Manager glows before the options panel was first opened."] = "Ein Fehler \"attempt to call global 'issecretvalue'\" durch Leuchteffekte des Abklingzeiten Managers vor dem ersten Öffnen des Optionsfensters wurde behoben."
L["Unlock Mode widget tooltips use Wrath-compatible alpha fades, fixing the SetFromAlpha error on Grow Right."] = "Tooltips der Widgets im Freigabemodus nutzen Wrath-kompatible Alpha-Überblendungen, was den SetFromAlpha-Fehler bei Grow Right behebt."
L["The options search results list has a fully opaque background with its results drawn above it, so sidebar and page text no longer bleeds into the results."] = "Die Ergebnisliste der Optionssuche hat einen vollständig deckenden Hintergrund mit den Ergebnissen darüber, sodass Text der Seitenleiste und Seite nicht mehr in die Ergebnisse durchscheint."
L["Unlock Mode no longer errors on SetMaxLines when it first opens, so element movers appear again."] = "Der Freigabemodus wirft beim ersten Öffnen keinen Fehler bei SetMaxLines mehr, sodass die Element-Mover wieder erscheinen."
L["The Patch Notes reminder dot now lights after each backport update."] = "Der Erinnerungspunkt der Patchnotes leuchtet jetzt nach jedem Backport-Update auf."
L["The options search results now draw above the sidebar and page instead of behind them."] = "Die Ergebnisse der Optionssuche werden jetzt über der Seitenleiste und der Seite gezeichnet statt dahinter."
L["The Unlock Mode right-click menu no longer closes right after opening when many elements are on screen."] = "Das Rechtsklickmenü des Freigabemodus schließt sich nicht mehr direkt nach dem Öffnen, wenn viele Elemente auf dem Bildschirm sind."
L["Opening the Raid Frames options no longer causes a stack overflow in Settings Overrides."] = "Das Öffnen der Optionen für Schlachtzugsfenster verursacht keinen Stapelüberlauf mehr in Einstellungs Überschreibungen."
L["Unlock Mode art, options page icons and the Unlock Mode top bar are now visible and readable."] = "Grafiken des Freigabemodus, Symbole der Optionsseiten und die obere Leiste des Freigabemodus sind jetzt sichtbar und lesbar."
L["The addon list shows clean module names, grouped under EllesmereUI in addon managers."] = "Die Addonliste zeigt saubere Modulnamen, gruppiert unter EllesmereUI in Addon-Managern."
L["Search Features and Search Module Settings accept typing again."] = "Funktionen suchen und Moduleinstellungen suchen nehmen wieder Eingaben an."
L["Clients whose atlas lookup errors on unknown names (such as custom 3.3.5 clients with Retail UI ports) no longer stop EllesmereUI files from loading."] = "Clients, deren Atlas-Abfrage bei unbekannten Namen Fehler wirft (etwa angepasste 3.3.5-Clients mit Retail-UI-Ports), verhindern nicht mehr das Laden von EllesmereUI-Dateien."
L["Like Retail 9.4, the DataBars page opens with a bar selector at the top: rename or delete a bar right in its menu, or pick + Create New DataBar. + New Bar shows the four starter templates as cards, and with no bars yet the page shows them as a card grid."] = "Wie in Retail 9.4 öffnet sich die Seite Datenleisten mit einer Leistenauswahl oben: benenne eine Leiste direkt in ihrem Menü um oder lösche sie, oder wähle + Neue Datenleiste erstellen. + Neue Leiste zeigt die vier Startvorlagen als Karten, und ohne Leisten zeigt die Seite sie als Kartenraster."
L["Like Retail 9.4, the options window has a Window Scale slider in its top corner that resizes it in smooth 5% steps; the mouse wheel over it, or Shift + mouse wheel anywhere on the window, works too. The credit to Ellesmere now sits under the close button."] = "Wie in Retail 9.4 hat das Optionsfenster oben in der Ecke einen Schieberegler Fensterskalierung, der es in sanften 5% Schritten skaliert; das Mausrad darüber oder Umschalt + Mausrad irgendwo im Fenster funktioniert auch. Der Dank an Ellesmere steht jetzt unter der Schließen-Taste."
L["Global Settings opens with Reset ALL EUI Addon Settings and Uninstall EUI side by side, like Retail 9.4. Reset ALL now asks you to type Confirm. Optimize My FPS and Graphics is gone: the graphics settings it changed do not exist on this client."] = "Globale Einstellungen öffnet sich mit ALLE EUI Addon Einstellungen zurücksetzen und EUI deinstallieren nebeneinander, wie in Retail 9.4. ALLE zurücksetzen verlangt jetzt die Eingabe von Confirm. Meine FPS und Grafik optimieren ist entfernt: die geänderten Grafikeinstellungen existieren auf diesem Client nicht."
L["Like Retail 9.4, each look card on the Style page has a menu of the modules using it: tick modules under another look, then press Apply Styles to switch them all with one reload. The menus list only looks this client can draw: Cooldown Manager, Minimap and Damage Meters offer EllesmereUI and Classic WoW UI, Player Aura Bars is gone, and Apply to All skips modules without that look."] = "Wie in Retail 9.4 hat jede Aussehenskarte auf der Seite Stil ein Menü der Module, die sie nutzen: hake Module unter einem anderen Aussehen an und drücke dann Stile anwenden, um alle mit einem Neuladen umzustellen. Die Menüs listen nur Aussehen, die dieser Client darstellen kann: Abklingzeiten Manager, Minikarte und Schadensmeter bieten EllesmereUI und Klassisches WoW UI, Spieler Aurenleisten ist entfernt, und Auf alle anwenden überspringt Module ohne dieses Aussehen."
L["The import page can update your current profile instead of making a new one: tick Import into current profile and the string's selected modules (for example only Nameplates) replace their settings there while the rest of the profile stays."] = "Die Importseite kann dein aktuelles Profil aktualisieren, statt ein neues zu erstellen: hake In aktuelles Profil importieren an, und die ausgewählten Module des Strings (zum Beispiel nur Namensplaketten) ersetzen dort ihre Einstellungen, während der Rest des Profils bleibt."
L["The EUI Staff page opens with thanks to Ellesmere and the port staff card with a GitHub link to the releases. The header line crediting Ellesmere opens it."] = "Die Seite EUI Staff öffnet sich mit einem Dank an Ellesmere und der Karte des Port-Teams mit einem GitHub-Link zu den Releases. Die Kopfzeile mit dem Dank an Ellesmere öffnet sie."
L["Custom spell reminders, visibility and sounds are saved separately for each character, independently of shared profiles."] = "Eigene Zaubererinnerungen, Sichtbarkeit und Sounds werden für jeden Charakter separat gespeichert, unabhängig von geteilten Profilen."
L["Optional achievement, trade and guild recruitment filters, plus your own blocked words and phrases."] = "Optionale Filter für Erfolge, Handel und Gildenrekrutierung, dazu deine eigenen gesperrten Wörter und Phrasen."
L["Configure repeat timing, sender matching and chat scopes from the new Spam Filter page."] = "Konfiguriere Wiederholungszeit, Absenderabgleich und Chatbereiche auf der neuen Seite Spamfilter."
L["Outline menus in the Nameplates and Unit Frames text cogs, and Zone Text Outline in Quality of Life. The Unit Frames preview shows each text's outline."] = "Konturmenüs in den Textzahnrädern von Namensplaketten und Einheitenfenstern sowie Zonentext-Kontur in Komfortfunktionen. Die Vorschau der Einheitenfenster zeigt die Kontur jedes Texts."
L["New PETS and DIMINISHING RETURNS sections, plus Fade Out of Range and its opacity under Target and Visibility."] = "Neue Bereiche BEGLEITER und ABNEHMENDE WIRKUNG sowie Außer Reichweite verblassen und dessen Deckkraft unter Ziel und Sichtbarkeit."
L["Announce Interrupts and Accept Invites from Friends & Guild in the GROUP section, and a Disband Group button on Raid Tools."] = "Unterbrechungen ankündigen und Einladungen von Freunden & Gilde annehmen im Bereich GRUPPE sowie eine Taste Gruppe auflösen in den Schlachtzugswerkzeugen."
L["Bar Display, Menu, Bags & XP Bars and Bar Animations, with a live preview of the selected bar. Click an icon, keybind or count to jump to its setting."] = "Leistenanzeige, Menü, Taschen & XP Leisten und Leistenanimationen, mit einer Live-Vorschau der ausgewählten Leiste. Klicke auf ein Symbol, eine Tastenbelegung oder eine Anzahl, um zu deren Einstellung zu springen."
L["The Raid and Party pages gain the Retail DISPELS section and a Preview Mode (Real, Overlay or No Preview) at the top."] = "Die Seiten Schlachtzug und Gruppe erhalten den Retail-Bereich BANNUNGEN und oben einen Vorschaumodus (Echt, Überlagerung oder Keine Vorschau)."
L["Party and Raid pages gain a TARGETED SPELLS section: mode, preview, icon size, maximum icons, position, growth, offsets, cast swipe, cast timer and interruptible colors."] = "Die Seiten Gruppe und Schlachtzug erhalten einen Bereich ANVISIERTE ZAUBER: Modus, Vorschau, Symbolgröße, maximale Symbole, Position, Wachstum, Versätze, Zauber-Wischtextur, Zaubertimer und Farben für unterbrechbare Zauber."
L["Raid Frames (Party and Raid) and Unit Frames (player, target, focus) gain an ABSORBS section for the estimated shields, with a shield in the Unit Frames preview."] = "Schlachtzugsfenster (Gruppe und Schlachtzug) und Einheitenfenster (Spieler, Ziel, Fokus) erhalten einen Bereich ABSORPTIONEN für die geschätzten Schilde, mit einem Schild in der Vorschau der Einheitenfenster."
L["CDM Bars now opens with Retail's bar dropdown (rename or delete custom bars, add Cooldowns, Utility, Buff or FocusKick bars) and the selected bar's icons: drag to reorder, click an icon to edit it, middle-click to remove it, and use + to add spells or buffs."] = "CDM Leisten öffnet sich jetzt mit dem Retail-Leisten-Dropdown (eigene Leisten umbenennen oder löschen, Leisten für Abklingzeiten, Nützliches, Stärkungszauber oder FocusKick hinzufügen) und den Symbolen der ausgewählten Leiste: ziehen zum Umsortieren, Klick auf ein Symbol zum Bearbeiten, Mittelklick zum Entfernen, und + zum Hinzufügen von Zaubern oder Stärkungszaubern."
L["Hide server announcements such as \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\", optionally keeping deaths from a chosen level up visible."] = "Blendet Serverankündigungen wie \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\" aus, wobei Tode ab einer gewählten Stufe optional sichtbar bleiben."
L["The FocusKick Cast Sound and the Chat sounds list EllesmereUI and SharedMedia sounds, and the Textures page links Damage Meters to its per-window Bar Texture"] = "Der FocusKick-Zaubersound und die Chatsounds listen EllesmereUI- und SharedMedia-Sounds, und die Seite Texturen verknüpft Schadensmeter mit seiner Leistentextur pro Fenster"
L["New dropdown at the top of Icons, with a link to apply it to every bar. The preview shows the shape."] = "Neues Dropdown oben bei Symbole, mit einem Link, um es auf jede Leiste anzuwenden. Die Vorschau zeigt die Form."
L["Boss Debuff Icon, Icon Size, Icon Offset Y and Show Dispellable When No Boss Debuff under Dispels"] = "Boss-Schwächungszaubersymbol, Symbolgröße, Symbolversatz Y und Bannbare zeigen, wenn kein Boss-Schwächungszauber unter Bannungen"
L["General, Layout, Health and Power, Text, Icons, Cast Bar and Target and Visibility sections"] = "Bereiche Allgemein, Layout, Gesundheit und Ressource, Text, Symbole, Zauberleiste sowie Ziel und Sichtbarkeit"
L["Display, Extras and Wrath Inventory settings, including Delete Saved Character"] = "Einstellungen für Anzeige, Extras und Wrath-Inventar, einschließlich Gespeicherten Charakter löschen"
L["Class icon themes, class colored names, borders, accent colors, faction banners and invite auto-accept"] = "Klassensymbol-Themen, Namen in Klassenfarbe, Rahmen, Akzentfarben, Fraktionsbanner und automatisches Annehmen von Einladungen"
L["Display, Colors, General and Aura Filters with inline color swatches and cog menus"] = "Anzeige, Farben, Allgemein und Aurenfilter mit eingebetteten Farbfeldern und Zahnradmenüs"
L["Quick Loot, Auto-Fill Delete Confirmation, Auto Repair and Auto Sell Junk in the Retail layout"] = "Schnell Plündern, Bestätigung beim Löschen automatisch ausfüllen, Automatisch reparieren und Müll automatisch verkaufen im Retail-Layout"
L["Display, Colors and Extras sections with inline swatches and auto accept and turn-in cogs"] = "Bereiche Anzeige, Farben und Extras mit eingebetteten Farbfeldern und Zahnrädern für automatisches Annehmen und Abgeben"
L["Wrath spell icons, real cast times and the same faction and portrait art as the live frames"] = "Wrath-Zaubersymbole, echte Zauberzeiten und dieselbe Fraktions- und Porträtgrafik wie die Live-Fenster"
L["The Active Profile dropdown shows the rename, delete and keybind icons on each profile again."] = "Das Dropdown Aktives Profil zeigt wieder die Symbole zum Umbenennen, Löschen und für die Tastenbelegung bei jedem Profil."
L["Dropdowns open again with !!!ClassicAPI installed; its clipping function no longer moves the menus into an empty scroll frame."] = "Dropdowns öffnen sich wieder mit installiertem !!!ClassicAPI; dessen Clipping-Funktion verschiebt die Menüs nicht mehr in einen leeren Scrollrahmen."
L["Resetting Global Settings no longer stops partway with an error and reloads the UI again."] = "Das Zurücksetzen der Globalen Einstellungen bricht nicht mehr mittendrin mit einem Fehler ab und lädt das UI wieder neu."
L["Options that do nothing on the Wrath client are hidden: image sharpening, Lag Tolerance, Combat Text Size, Swiftmend dim, Slug outline, class resource dark mode and colors, Retail-only class and power colors, and cursor ring textures."] = "Optionen, die auf dem Wrath-Client nichts bewirken, sind ausgeblendet: Bildschärfung, Latenztoleranz, Kampftext Größe, Rasche Heilung-Abdunkeln, Slug-Kontur, Dunkelmodus und Farben der Klassenressourcen, reine Retail-Klassen- und Ressourcenfarben sowie Mauszeigerring-Texturen."
L["Global Settings no longer shows the Gamepad page, which has nothing to control on the Wrath client."] = "Globale Einstellungen zeigt die Seite Gamepad nicht mehr, da es auf dem Wrath-Client dort nichts zu steuern gibt."
L["Max Camera Distance saves and keeps its value instead of resetting to 1.0, and goes up to 4 like the Wrath client allows."] = "Maximale Kameradistanz speichert und behält ihren Wert, statt auf 1.0 zurückzuspringen, und geht bis 4, wie es der Wrath-Client erlaubt."
L["CDM Bars and Tracking Bars open without an \"attempt to call field 'disabled'\" error, and nine toggles show their tooltips again."] = "CDM Leisten und Verfolgungsleisten öffnen sich ohne den Fehler \"attempt to call field 'disabled'\", und neun Schalter zeigen wieder ihre Tooltips."
L["Chat > Spam Filter: the chat type settings stay usable when only the trade or recruitment filter is on, and the tooltips explain what each one covers."] = "Chat > Spamfilter: Die Einstellungen für Chattypen bleiben nutzbar, wenn nur der Handels- oder Rekrutierungsfilter aktiv ist, und die Tooltips erklären, was jeder abdeckt."
L["Opening the options no longer makes later Blizzard actions risk being blocked in EllesmereUI's name."] = "Das Öffnen der Optionen lässt spätere Blizzard-Aktionen nicht mehr Gefahr laufen, im Namen von EllesmereUI blockiert zu werden."
L["Checklist menus such as Visibility tick and untick their boxes as soon as they are clicked, even when the module's live update runs into a problem, instead of only after closing and reopening the menu."] = "Checklistenmenüs wie Sichtbarkeit haken ihre Kästchen sofort beim Klicken an und ab, auch wenn die Live-Aktualisierung des Moduls auf ein Problem stößt, statt erst nach dem Schließen und erneuten Öffnen des Menüs."
L["Dropdown lists, checklists and other option popups draw their items above their own background, on a solid background, instead of showing faded items with the page bleeding through."] = "Dropdownlisten, Checklisten und andere Options-Popups zeichnen ihre Einträge über ihrem eigenen Hintergrund, auf einem deckenden Hintergrund, statt verblasste Einträge mit durchscheinender Seite zu zeigen."
L["The Style page now keeps the Unit Frames health colors per look, so switching between Classic WoW UI and the EllesmereUI look keeps each one's colors."] = "Die Seite Stil behält jetzt die Gesundheitsfarben der Einheitenfenster pro Aussehen, sodass beim Wechsel zwischen Klassisches WoW UI und dem EllesmereUI-Aussehen jedes seine Farben behält."
L["The Unit Frames preview and power color swatches show the original game power colors under Classic WoW UI."] = "Die Vorschau der Einheitenfenster und die Farbfelder der Ressourcenfarben zeigen unter Klassisches WoW UI die originalen Ressourcenfarben des Spiels."
L["Each Core Text Position row, Spell Name, Cast Timer and Friendly Names now has its own gear for the outline instead of hiding it in the size popup."] = "Jede Zeile von Kerntextposition, Zaubername, Zaubertimer und Freundliche Namen hat jetzt ein eigenes Zahnrad für die Kontur, statt sie im Größen-Popup zu verstecken."
L["Pressing Esc to close Blizzard windows no longer shows \"EllesmereUIOptions has been blocked from an action\"."] = "Das Schließen von Blizzard-Fenstern mit Esc zeigt nicht mehr \"EllesmereUIOptions has been blocked from an action\"."
L["Combat damage, healing, periodic and pet damage toggles use Wrath's own combat text settings."] = "Die Schalter für Kampfschaden, Heilung, periodischen und Begleiterschaden nutzen die eigenen Kampftext-Einstellungen von Wrath."
L["Hidden option widgets no longer take keyboard focus after other windows close with Escape."] = "Ausgeblendete Options-Widgets übernehmen nicht mehr den Tastaturfokus, nachdem andere Fenster mit Escape geschlossen wurden."
L["Dragging or typing in a slider no longer errors."] = "Ziehen oder Tippen in einem Schieberegler wirft keinen Fehler mehr."
L["The settings panel opens on clients whose atlas lookup errors on unknown names, instead of failing with an 'NS' error."] = "Das Einstellungsfenster öffnet sich auf Clients, deren Atlas-Abfrage bei unbekannten Namen Fehler wirft, statt mit einem 'NS'-Fehler zu scheitern."
L["Displays has a ZONE TEXT section with Move Zone Text."] = "Anzeigen hat einen Bereich ZONENTEXT mit Zonentext bewegen."
L["Raid Tools no longer has a BOSS MOD BARS section: AbilityTimeline's Sources options hide DBM and BigWigs bars."] = "Schlachtzugswerkzeuge hat keinen Bereich BOSS MOD BARS mehr: die Quellen-Optionen von AbilityTimeline blenden DBM- und BigWigs-Leisten aus."
L["The Retail raid panel: show it never, in raids, in any group or always, as a resizable Compact Band, one or two windows, or only one part. It can start as a small icon, opens and closes with a keybind even in combat, and has three pull timers, Convert and Disband. Reinvite removes everyone and invites them back to the same kind of group, and Convert to Party rebuilds a raid of five or fewer as a party the same way. Shift + Left Click a marker to place its world marker when the marker item is in your bags, or Shift + Left Click the clear icon to reset world markers. In a raid it only shows for the leader and assistants."] = "Das Retail-Schlachtzugsfeld: zeige es nie, in Schlachtzügen, in jeder Gruppe oder immer, als skalierbares Kompaktes Band, ein oder zwei Fenster oder nur einen Teil. Es kann als kleines Symbol starten, öffnet und schließt sich per Tastenbelegung auch im Kampf und hat drei Pull-Timer, Umwandeln und Auflösen. Neu einladen entfernt alle und lädt sie erneut in dieselbe Gruppenart ein, und In Gruppe umwandeln baut einen Schlachtzug mit fünf oder weniger Spielern auf dieselbe Weise als Gruppe neu auf. Umschalt + Linksklick auf eine Markierung setzt ihren Weltmarker, wenn der Markierungsgegenstand in deinen Taschen ist, oder Umschalt + Linksklick auf das Entfernen-Symbol setzt die Weltmarker zurück. Im Schlachtzug wird es nur für Anführer und Assistenten angezeigt."
L["One key casts Misdirection or Tricks of the Trade on your focus, the tank (typed name, Main Tank or tank role), your friendly target or your pet. An icon shows who it will go to, the buff timer and the cooldown. Bind it in Key Bindings."] = "Eine Taste wirkt Irreführung oder Schurkenhandel auf deinen Fokus, den Tank (eingegebener Name, Haupttank oder Tankrolle), dein freundliches Ziel oder deinen Begleiter. Ein Symbol zeigt, auf wen es geht, den Timer des Stärkungszaubers und die Abklingzeit. Belege es unter Tastaturbelegung."
L["Damage taken, healing, avoids and entering or leaving combat scroll above the player frame instead of Blizzard's combat text, with Straight, Fountain or Static animations, colors per type and a mover in Unlock Mode."] = "Erlittener Schaden, Heilung, Vermeidungen und Kampfbeginn oder -ende scrollen über dem Spielerfenster statt des Blizzard-Kampftexts, mit den Animationen Gerade, Fontäne oder Statisch, Farben pro Typ und einem Mover im Freigabemodus."
L["Picks an NPC's only dialog option for you. Hold Shift to skip it; instances and NPCs with quests to take or turn in are left alone. Its cog can also skip past low level quests."] = "Wählt die einzige Dialogoption eines NPCs für dich. Halte Umschalt, um es zu überspringen; Instanzen und NPCs mit anzunehmenden oder abzugebenden Quests bleiben unberührt. Sein Zahnrad kann auch niedrigstufige Quests überspringen."
L["An arrow next to the To box lists your alts on this realm and faction, guild members and the last names you mailed. Click a name to fill it in."] = "Ein Pfeil neben dem Feld An listet deine Twinks auf diesem Realm und dieser Fraktion, Gildenmitglieder und die zuletzt angeschriebenen Namen. Klicke auf einen Namen, um ihn einzutragen."
L["Pick None, Outline, Thick Outline or Shadow for the zone, sub-zone and PvP text shown when entering an area. Blizzard Default keeps the game's own font."] = "Wähle Keine, Kontur, Dicke Kontur oder Schatten für den Zonen-, Unterzonen- und PvP-Text beim Betreten eines Gebiets. Blizzard Standard behält die eigene Schriftart des Spiels."
L["Posts the spell you or your pet interrupted, with a spell link, to Say, Emote, Party or Raid. Party and Raid switch to the battleground channel inside battlegrounds."] = "Postet den Zauber, den du oder dein Begleiter unterbrochen habt, mit Zauberlink in Sagen, Emote, Gruppe oder Schlachtzug. Gruppe und Schlachtzug wechseln in Schlachtfeldern zum Schlachtfeldkanal."
L["Group invites from your friends list and guildmates are accepted automatically, unless you are already grouped or queued in the Dungeon Finder."] = "Gruppeneinladungen von deiner Freundesliste und Gildenmitgliedern werden automatisch angenommen, außer du bist bereits in einer Gruppe oder im Dungeonbrowser angemeldet."
L["A Disband button on Raid Tools removes everyone from your raid or party after a confirmation. Leader only, never in combat."] = "Eine Taste Auflösen in den Schlachtzugswerkzeugen entfernt nach einer Bestätigung alle aus deinem Schlachtzug oder deiner Gruppe. Nur für Anführer, nie im Kampf."
L["Loots everything instantly even with Blizzard's Auto Loot off; hold Shift to see the loot window. Locked slots such as group rolls and master loot are skipped."] = "Plündert alles sofort, auch wenn das automatische Plündern von Blizzard aus ist; halte Umschalt, um das Beutefenster zu sehen. Gesperrte Plätze wie Gruppenwürfe und Plündermeister werden übersprungen."
L["FPS and latency, secondary stats, durability warning, combat and death alerts, a crosshair and a new target distance text, all movable in Unlock Mode."] = "FPS und Latenz, Sekundärwerte, Haltbarkeitswarnung, Kampf- und Todeswarnungen, ein Fadenkreuz und ein neuer Text für die Zielentfernung, alles im Freigabemodus bewegbar."
L["The FPS counter's new default Text Color, Quality, turns FPS and each latency value green, yellow or red (60/30 fps, 100/250 ms). Custom and Class Color remain available."] = "Die neue Standard-Textfarbe des FPS-Zählers, Qualität, färbt FPS und jeden Latenzwert grün, gelb oder rot (60/30 fps, 100/250 ms). Eigene und Klassenfarbe bleiben verfügbar."
L["Alert sounds from SharedMedia packs that load after Quality of Life play too"] = "Warnsounds aus SharedMedia-Paketen, die nach Komfortfunktionen geladen werden, werden ebenfalls abgespielt"
L["An Open All button takes items and gold one letter at a time, skipping COD and GM mail"] = "Eine Taste Alle öffnen nimmt Gegenstände und Gold Brief für Brief, wobei Nachnahme- und GM-Post übersprungen wird"
L["With Send Mail open, Shift-click a bag item to attach it and matching items"] = "Bei geöffnetem Post verschicken Umschalt-Klick auf einen Taschengegenstand, um ihn und passende Gegenstände anzuhängen"
L["Opens lootable containers one at a time out of combat (off by default)"] = "Öffnet plünderbare Behälter einzeln außerhalb des Kampfes (standardmäßig aus)"
L["A Train All button beside Train shows how many spells are available and the total cost"] = "Eine Taste Alles erlernen neben Erlernen zeigt, wie viele Zauber verfügbar sind und die Gesamtkosten"
L["Pull timer length, DBM/BigWigs broadcast and a chat countdown"] = "Pull-Timer-Dauer, DBM/BigWigs-Übertragung und ein Chat-Countdown"
L["Raid Tools keeps its size after importing a Retail profile."] = "Schlachtzugswerkzeuge behält seine Größe nach dem Import eines Retail-Profils."
L["Shift-click mail attach no longer replaces the bag item click handler, so bag clicks stay free of taint."] = "Umschalt-Klick zum Anhängen an Post ersetzt nicht mehr den Klick-Handler der Taschengegenstände, sodass Taschenklicks frei von Taint bleiben."
L["Hiding DBM and BigWigs bars while AbilityTimeline is active moved to AbilityTimeline itself, as on Retail: Hide DBM bars and Hide BigWigs bars on its Sources page. The Raid Tools option is gone."] = "Das Ausblenden von DBM- und BigWigs-Leisten bei aktivem AbilityTimeline ist zu AbilityTimeline selbst gewandert, wie auf Retail: Hide DBM bars und Hide BigWigs bars auf dessen Seite Sources. Die Option der Schlachtzugswerkzeuge ist entfernt."
L["Logging out, exiting, releasing spirit and other Blizzard confirmation popups no longer trigger the \"EllesmereUIQoL has been blocked from an action only available to the Blizzard UI\" message."] = "Ausloggen, Beenden, Geist freilassen und andere Blizzard-Bestätigungspopups lösen nicht mehr die Meldung \"EllesmereUIQoL has been blocked from an action only available to the Blizzard UI\" aus."
L["The zone name no longer appears in the middle of the screen at small UI scales. It now sits fixed at the top (X 9 / Y 322 from screen center), with no Unlock Mode mover."] = "Der Zonenname erscheint bei kleinen UI-Skalierungen nicht mehr in der Bildschirmmitte. Er sitzt jetzt fest oben (X 9 / Y 322 von der Bildschirmmitte), ohne Mover im Freigabemodus."
L["Show Player Buffs puts the hovered player's buffs as icons beside the tooltip, with position, size, icons per row and offsets."] = "Stärkungszauber des Spielers anzeigen setzt die Stärkungszauber des überfahrenen Spielers als Symbole neben den Tooltip, mit Position, Größe, Symbolen pro Reihe und Versätzen."
L["Hovering a stat in the character sheet sidebar glows the equipped items that give it."] = "Beim Überfahren eines Werts in der Seitenleiste des Charakterfensters leuchten die angelegten Gegenstände, die ihn gewähren."
L["Inspect Enchants and Missing Enhancements"] = "Verzauberungen beim Betrachten und fehlende Verbesserungen"
L["Inspect enchants show as an icon with the name on hover, or as names tinted by item quality, in their own size. At max level, red badges flag missing enchants, empty sockets and a missing belt buckle, as on your character sheet."] = "Verzauberungen beim Betrachten erscheinen als Symbol mit dem Namen beim Überfahren oder als nach Gegenstandsqualität getönte Namen, in eigener Größe. Auf Höchststufe markieren rote Abzeichen fehlende Verzauberungen, leere Sockel und eine fehlende Gürtelschnalle, wie in deinem Charakterfenster."
L["Saving an equipment set rebuilds the native icon picker even when already open, preventing the PaperDollFrame nil comparison error."] = "Das Speichern eines Ausrüstungssets baut die native Symbolauswahl neu auf, auch wenn sie schon offen ist, und verhindert so den nil-Vergleichsfehler von PaperDollFrame."
L["Need, Greed, Disenchant and Pass buttons on loot rolls count what the rest of the group picked. Hover a button to see who, in class colors."] = "Die Tasten Bedarf, Gier, Entzaubern und Passen bei Beutewürfen zählen, was der Rest der Gruppe gewählt hat. Fahre über eine Taste, um zu sehen wer, in Klassenfarben."
L["Player tooltips show GearScore in the GearScoreLite colors, using its formula when it is loaded. GearScoreLite's own line is kept when its option is on."] = "Spielertooltips zeigen GearScore in den Farben von GearScoreLite und nutzen dessen Formel, wenn es geladen ist. Die eigene Zeile von GearScoreLite bleibt erhalten, wenn dessen Option aktiv ist."
L["Enchants and gems on every slot, lowest durability, model rotate, pan and zoom, reorderable stat sections and a socket strip that fills sockets from your bags."] = "Verzauberungen und Edelsteine an jedem Platz, niedrigste Haltbarkeit, Modell drehen, verschieben und zoomen, umsortierbare Wertebereiche und eine Sockelleiste, die Sockel aus deinen Taschen füllt."
L["Class colored names and health bar, guild rank, target, item level and a cursor or fixed anchor"] = "Namen und Gesundheitsleiste in Klassenfarbe, Gildenrang, Ziel, Gegenstandsstufe und ein Anker am Mauszeiger oder fest"
L["Item levels on inspect, docking beside the character window and a merchant list mode"] = "Gegenstandsstufen beim Betrachten, Andocken neben dem Charakterfenster und ein Listenmodus beim Händler"
L["Resurrect accept glow and a Dungeon Ready countdown bar"] = "Leuchten beim Annehmen einer Wiederbelebung und eine Countdownleiste für Dungeon bereit"
L["The server's Collections and Wardrobe & Transmog windows join the window skins"] = "Die Server-Fenster Sammlungen sowie Garderobe & Transmogrifikation werden in die Fenster Skins aufgenommen"
L["Barber Shop, PvP and battlemasters, Arena Registrar, battleground score, minimap and capture bar, Help and GM tickets, GM chat status, breath and fatigue timers, stopwatch, raid pullouts, debug tools and Ace3 config windows"] = "Barbier, PvP und Kampfmeister, Arenaregistrator, Schlachtfeldpunktestand, Minikarte und Eroberungsleiste, Hilfe- und GM-Tickets, GM-Chatstatus, Atem- und Erschöpfungstimer, Stoppuhr, Schlachtzugsgruppenfenster, Debug-Werkzeuge und Ace3-Konfigurationsfenster"
L["Ready checks no longer leave an empty black panel for the leader or after you answer."] = "Bereitschaftsabfragen hinterlassen kein leeres schwarzes Feld mehr für den Anführer oder nach deiner Antwort."
L["The character sheet Titles tab lists your known titles again; click one to wear it."] = "Der Reiter Titel im Charakterfenster listet wieder deine bekannten Titel; klicke einen an, um ihn zu tragen."
L["The Guild Message Of The Day popup (and other wide text popups) no longer covers its title and buttons with the input box."] = "Das Popup der Gildennachricht des Tages (und andere breite Text-Popups) verdeckt Titel und Tasten nicht mehr mit dem Eingabefeld."
L["The Achievements window no longer darkens the achievement list behind its border."] = "Das Erfolgsfenster dunkelt die Erfolgsliste hinter seinem Rahmen nicht mehr ab."
L["The AddOn List window skin toggle only shows when the client has an AddOn List window."] = "Der Skin-Schalter für das Fenster AddOn-Liste erscheint nur, wenn der Client ein AddOn-Listenfenster hat."
L["Send Mail shows the To, Subject and message boxes again, and the typing cursor stays visible in skinned edit boxes."] = "Post verschicken zeigt wieder die Felder An, Betreff und Nachricht, und der Eingabecursor bleibt in gestalteten Eingabefeldern sichtbar."
L["The fixed tooltip anchor no longer snaps back to its saved spot while you drag it in Unlock Mode."] = "Der feste Tooltip-Anker springt nicht mehr an seine gespeicherte Stelle zurück, während du ihn im Freigabemodus ziehst."
L["Auction House: panels and tabs added by Auctionator and other auction addons keep their own look and layout, and the footer Close buttons no longer get an \"x\" over their text."] = "Auktionshaus: Von Auctionator und anderen Auktions-Addons hinzugefügte Felder und Reiter behalten ihr eigenes Aussehen und Layout, und die Schließen-Tasten in der Fußzeile bekommen kein \"x\" mehr über ihren Text."
L["Talents: the close button and the points footer end at the scroll bar instead of past the window edge."] = "Talente: Die Schließen-Taste und die Punkte-Fußzeile enden an der Bildlaufleiste statt über den Fensterrand hinaus."
L["Window tabs keep their dark background instead of showing through."] = "Fensterreiter behalten ihren dunklen Hintergrund, statt durchsichtig zu werden."
L["World map: the player arrow, party and raid dots, corpse and quest markers stay on the map art after a map view change during combat, including instance maps."] = "Weltkarte: Spielerpfeil, Gruppen- und Schlachtzugspunkte, Leichnam- und Questmarkierungen bleiben nach einem Wechsel der Kartenansicht im Kampf auf der Kartengrafik, auch auf Instanzkarten."
L["Native dropdown menus no longer show an empty square at the right of each row."] = "Native Dropdownmenüs zeigen kein leeres Quadrat mehr rechts in jeder Zeile."
L["Dropdown boxes in Blizzard windows, such as the Dungeon Finder type, end at their arrow instead of past the window edge."] = "Dropdownfelder in Blizzard-Fenstern, etwa der Typ im Dungeonbrowser, enden an ihrem Pfeil statt über den Fensterrand hinaus."
L["Raid Information: the background covers the whole window, including the title, close button, last row and the Extend Raid Lock and Close buttons."] = "Schlachtzugsinformationen: Der Hintergrund bedeckt das ganze Fenster, einschließlich Titel, Schließen-Taste, letzter Zeile und den Tasten Schlachtzugssperre verlängern und Schließen."
L["The Talents and Glyphs background now ends above the tabs and beside the dual spec tabs."] = "Der Hintergrund von Talenten und Glyphen endet jetzt über den Reitern und neben den Reitern der dualen Talentspezialisierung."
L["The Glyphs tab shows its native parchment background again, aligned with the glyph sockets."] = "Der Reiter Glyphen zeigt wieder seinen nativen Pergamenthintergrund, ausgerichtet an den Glyphensockeln."
L["Sliders in Blizzard windows, such as the Camera and Mouse options, are back to their normal size."] = "Schieberegler in Blizzard-Fenstern, etwa in den Kamera- und Mausoptionen, haben wieder ihre normale Größe."
L["Hide Until Usable and Hide Outside Form/Stance"] = "Bis benutzbar ausblenden und Außerhalb von Gestalt/Haltung ausblenden"
L["New Cooldown States: Hide Until Usable shows a spell only while it can be cast and is off cooldown (Overpower, Revenge, Victory Rush, Execute); low resources do not hide it. Hide Outside Form/Stance shows it only in the form or stance it needs. Both can close the gap or keep the place."] = "Neue Abklingzeitzustände: Bis benutzbar ausblenden zeigt einen Zauber nur, solange er gewirkt werden kann und nicht in Abklingzeit ist (Überwältigen, Rache, Siegesrausch, Hinrichten); zu wenig Ressourcen blendet ihn nicht aus. Außerhalb von Gestalt/Haltung ausblenden zeigt ihn nur in der benötigten Gestalt oder Haltung. Beide können die Lücke schließen oder den Platz behalten."
L["The + menu adds an Empty Slot that keeps a position free on the bar, to group icons."] = "Das Menü + fügt einen Leeren Platz hinzu, der eine Position auf der Leiste freihält, um Symbole zu gruppieren."
L["Bars can switch to a Shaped swipe that follows round icons and takes a Swipe Color, instead of the client's dark square sweep."] = "Leisten können auf eine geformte Wischtextur wechseln, die runden Symbolen folgt und eine Wischfarbe übernimmt, statt der dunklen quadratischen Wischtextur des Clients."
L["Cooldowns, Utility and Buffs bars plus custom bars and a FocusKick bar, tracked from your spellbook, cooldowns and auras. Lists are saved per talent group."] = "Leisten für Abklingzeiten, Nützliches und Stärkungszauber sowie eigene Leisten und eine FocusKick-Leiste, verfolgt aus deinem Zauberbuch, Abklingzeiten und Auren. Listen werden pro Talentgruppe gespeichert."
L["Aura or cooldown bars for player, target, focus or pet with textures, gradients, stack ticks and pandemic glow, arranged in groups."] = "Auren- oder Abklingzeitleisten für Spieler, Ziel, Fokus oder Begleiter mit Texturen, Farbverläufen, Stapelmarkierungen und Pandemie-Leuchten, in Gruppen angeordnet."
L["The + buttons above the bar icons open Retail's add menu: custom spell, item or slot, trinkets, racial, potions and your learned spells, or buffs and buff presets from the gold +"] = "Die Tasten + über den Leistensymbolen öffnen das Retail-Hinzufügen-Menü: eigener Zauber, Gegenstand oder Platz, Schmuckstücke, Volksfähigkeit, Tränke und deine erlernten Zauber, oder Stärkungszauber und Stärkungszauber-Voreinstellungen über das goldene +"
L["Passive proc trinkets in the trinket slots show their icon and the internal cooldown after each proc, with the proc buff while it lasts"] = "Passive Proc-Schmuckstücke in den Schmuckstückplätzen zeigen ihr Symbol und die interne Abklingzeit nach jedem Proc, mit dem Proc-Stärkungszauber, solange er anhält"
L["Tracking bar textures include SharedMedia, and the FocusKick Cast Sound adds EllesmereUI and SharedMedia sounds to the Blizzard ones"] = "Texturen der Verfolgungsleisten enthalten SharedMedia, und der FocusKick-Zaubersound ergänzt die Blizzard-Sounds um EllesmereUI- und SharedMedia-Sounds"
L["Light up EllesmereUI, Blizzard or ElvUI action buttons while an aura is active or missing"] = "Lässt EllesmereUI-, Blizzard- oder ElvUI-Aktionstasten leuchten, während eine Aura aktiv ist oder fehlt"
L["Always show, dim, hide on cooldown or when ready, and glow when ready"] = "Immer anzeigen, abdunkeln, bei Abklingzeit oder bei Bereitschaft ausblenden und bei Bereitschaft leuchten"
L["Racials, healthstones, Wrath potions and buffs such as Heroism and Bloodlust"] = "Volksfähigkeiten, Gesundheitssteine, Wrath-Tränke und Stärkungszauber wie Heldentum und Kampfrausch"
L["Show an entry only when a chosen talent is learned"] = "Zeigt einen Eintrag nur, wenn ein gewähltes Talent erlernt ist"
L["Utility bar options no longer switch to Buffs after a click, and the Cooldowns bar is no longer replaced by a second Buffs bar."] = "Optionen der Leiste Nützliches wechseln nach einem Klick nicht mehr zu Stärkungszauber, und die Leiste Abklingzeiten wird nicht mehr durch eine zweite Stärkungszauberleiste ersetzt."
L["Racials show once: the Utility bar no longer lists Arcane Torrent (and other racials with class variants) three times."] = "Volksfähigkeiten erscheinen nur einmal: die Leiste Nützliches listet Arkaner Strom (und andere Volksfähigkeiten mit Klassenvarianten) nicht mehr dreimal."
L["A passive trinket in a trinket slot shows its own icon in the options instead of a question mark."] = "Ein passives Schmuckstück in einem Schmuckstückplatz zeigt in den Optionen sein eigenes Symbol statt eines Fragezeichens."
L["Bars saved twice or under another bar's name (two Buffs bars and no Cooldowns) are repaired, so each built-in bar keeps its own icons and options."] = "Doppelt oder unter dem Namen einer anderen Leiste gespeicherte Leisten (zwei Stärkungszauberleisten und keine Abklingzeiten) werden repariert, sodass jede eingebaute Leiste ihre eigenen Symbole und Optionen behält."
L["Auto Sized and Even Split bars with Retail backgrounds, borders and screen edge snapping, plus per-block margins, alignment, scale and colors."] = "Leisten mit Automatische Größe und Gleichmäßige Aufteilung mit Retail-Hintergründen, Rahmen und Einrasten am Bildschirmrand, dazu Abstände, Ausrichtung, Skalierung und Farben pro Block."
L["20 Wrath Blocks"] = "20 Wrath-Blöcke"
L["Clock, FPS, latency, location, gold history, bags, durability, XP and reputation, dual spec, professions, travel, micro menu, currency and more."] = "Uhr, FPS, Latenz, Ort, Goldverlauf, Taschen, Haltbarkeit, EP und Ruf, duale Talentspezialisierung, Berufe, Reisen, Mikromenü, Währungen und mehr."
L["Latency text is green, yellow or red by connection quality by default. A Latency swatch in Text Color switches back to it after picking another color."] = "Der Latenztext ist standardmäßig je nach Verbindungsqualität grün, gelb oder rot. Ein Latenz-Farbfeld in Textfarbe schaltet nach Wahl einer anderen Farbe dorthin zurück."
L["Column tooltips with clickable rows and secure spell, item and macro lines"] = "Spalten-Tooltips mit anklickbaren Zeilen und sicheren Zauber-, Gegenstands- und Makrozeilen"
L["Every bar has a mover whose Element Options opens that bar's settings"] = "Jede Leiste hat einen Mover, dessen Element Optionen die Einstellungen dieser Leiste öffnet"
L["Profiles from 0.2 are converted automatically"] = "Profile aus 0.2 werden automatisch konvertiert"
L["Bars snapped to a screen edge or set to full length start in their place after login instead of needing Unlock Mode opened and closed."] = "Am Bildschirmrand eingerastete oder auf volle Länge gesetzte Leisten starten nach dem Einloggen an ihrem Platz, statt dass der Freigabemodus geöffnet und geschlossen werden muss."
L["The cast bar latency zone works for queued spells and remains visible during channels, with configurable color and millisecond text."] = "Die Latenzzone der Zauberleiste funktioniert für vorgemerkte Zauber und bleibt bei kanalisierten Zaubern sichtbar, mit einstellbarer Farbe und Millisekundentext."
L["Class, Power and Health Bars, Cast Bar, GCD Bar, Swing Timer and Totem Bar, each element with its own Unlock Mode mover. Older profiles migrate once."] = "Klassen-, Ressourcen- und Gesundheitsleisten, Zauberleiste, GCD Leiste, Schlagtimer und Totemleiste, jedes Element mit eigenem Mover im Freigabemodus. Ältere Profile werden einmalig migriert."
L["Main hand, off hand and ranged swings from the combat log, with queued Heroic Strike, Cleave and Maul, parry haste and speed changes."] = "Schwünge von Waffenhand, Schildhand und Fernkampf aus dem Kampflog, mit vorgemerktem Heldenhafter Stoß, Spalten und Zermalmen, Parierbeschleunigung und Tempowechseln."
L["Bar textures include textures from SharedMedia and other addons"] = "Leistentexturen enthalten Texturen aus SharedMedia und anderen Addons"
L["Vertical bars, Retail texts, gradients, thresholds, tick marks and smoothing"] = "Vertikale Leisten, Retail-Texte, Farbverläufe, Schwellenwerte, Markierungsstriche und Glättung"
L["Death Knight rune order and countdowns, combo points, or Blizzard's own art"] = "Runenreihenfolge und Countdowns für Todesritter, Combopunkte oder die eigene Grafik von Blizzard"
L["Channel ticks, latency, total duration and uninterruptible colors"] = "Kanalisierungsticks, Latenz, Gesamtdauer und Farben für nicht unterbrechbare Zauber"
L["Totem icons and timers, and a movable Call Totem Bar"] = "Totemsymbole und -timer sowie eine bewegbare Totemrufleiste"
L["The Call Totem Bar no longer resizes or moves during combat; changes apply when combat ends."] = "Die Totemrufleiste ändert im Kampf nicht mehr Größe oder Position; Änderungen gelten nach Kampfende."
L["The player cast bar shows the channeled spell's name instead of \"Channeling\"."] = "Die Zauberleiste des Spielers zeigt den Namen des kanalisierten Zaubers statt \"Channeling\"."
L["Class icons in the EUI themes, status orbs, notes in the details line, faction banners and hover highlight, with borders and accent colors."] = "Klassensymbole in den EUI-Themen, Statuskugeln, Notizen in der Detailzeile, Fraktionsbanner und Mouseover-Hervorhebung, mit Rahmen und Akzentfarben."
L["Accepts group invites from friends, and optionally from guild members, and closes the popup."] = "Nimmt Gruppeneinladungen von Freunden und optional von Gildenmitgliedern an und schließt das Popup."
L["The window stays native but rows still get class icons and colored names"] = "Das Fenster bleibt nativ, aber Zeilen erhalten trotzdem Klassensymbole und farbige Namen"
L["Auto Accept picks quests from NPC dialogs, with Prevent Multi Quest Accept, and Auto Turn In completes single-reward quests. Hold Shift to skip."] = "Automatisch annehmen nimmt Quests aus NPC-Dialogen an, mit Mehrfaches Annehmen von Quests verhindern, und Automatisch abgeben schließt Quests mit nur einer Belohnung ab. Halte Umschalt zum Überspringen."
L["Uses the item of your tracked quest, found in the quest log, and only holds the key while there is an item to use."] = "Benutzt den Gegenstand deiner verfolgten Quest, im Questlog gefunden, und belegt die Taste nur, solange es einen Gegenstand zu benutzen gibt."
L["The top line uses the accent color and Line Color tints the header divider"] = "Die oberste Linie nutzt die Akzentfarbe, und Linienfarbe tönt den Trenner der Kopfzeile"
L["/eqt show, /eqt hide and /eqt toggle"] = "/eqt show, /eqt hide und /eqt toggle"
L["Clear your focus by clicking the focus frame (Shift + Right Click by default, or Ctrl/Alt + Right Click, Middle Click, Shift + Left Click). Set it on the Focus frame page. Works in combat."] = "Entferne deinen Fokus durch Klicken auf das Fokusfenster (standardmäßig Umschalt + Rechtsklick, oder Strg/Alt + Rechtsklick, Mittelklick, Umschalt + Linksklick). Einstellbar auf der Seite des Fokusfensters. Funktioniert im Kampf."
L["Two new debuff filter modes: Raid Debuffs shows the common raid debuffs from anyone (armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements and Hunter's Mark), and Own and Raid Debuffs adds yours."] = "Zwei neue Filtermodi für Schwächungszauber: Schlachtzug Schwächungszauber zeigt die üblichen Schlachtzug-Schwächungszauber von allen (Rüstung, erlittener Zauber- und körperlicher Schaden, erlittene kritische Treffer, Angriffskraft, Angriffs- und Zaubertempo, erhaltene Heilung, Richturteile und Mal des Jägers), und Eigene und Schlachtzug Schwächungszauber fügt deine hinzu."
L["Type Icon Position puts the icon of the player's highest dispellable debuff type on a point of the health bar, with its size and offsets in the cog. Only Dispellable by You now sits beside it and narrows the overlay, icon and border colors alike."] = "Position des Typ Symbols setzt das Symbol des höchsten bannbaren Schwächungszaubertyps des Spielers auf einen Punkt der Gesundheitsleiste, mit Größe und Versätzen im Zahnrad. Nur von Dir bannbar steht jetzt daneben und schränkt Überlagerung, Symbol und Rahmenfarben gleichermaßen ein."
L["The focus frame gets the aura Border Style, size and color settings, as player and target have."] = "Das Fokusfenster erhält die Einstellungen für Aurenrahmenstil, Größe und Farbe, wie Spieler und Ziel."
L["Player, target and focus show incoming heals past the health fill: yours and other players' in their own colors, from LibHealComm-4.0 (only healers running a HealComm addon are seen)."] = "Spieler, Ziel und Fokus zeigen eingehende Heilungen hinter der Gesundheitsfüllung: deine und die anderer Spieler in eigenen Farben, aus LibHealComm-4.0 (nur Heiler mit einem HealComm-Addon werden erkannt)."
L["The debuff filters can now show or hide Sated, Exhaustion and the other Bloodlust lockout debuffs. They stay hidden by default."] = "Die Schwächungszauberfilter können jetzt Gesättigt, Erschöpfung und die anderen Kampfrausch-Sperrschwächungszauber anzeigen oder ausblenden. Standardmäßig bleiben sie ausgeblendet."
L["Left, Right, Center and Extra Text, the Bottom Text Bar texts and Power Percent each have an Outline choice under Size: None, Outline, Thick Outline or Shadow, or the module default."] = "Linker, Rechter, Zentrierter und Zusatztext, die Texte der unteren Textleiste und Ressourcenprozent haben je eine Konturauswahl unter Größe: Keine, Kontur, Dicke Kontur oder Schatten, oder der Modulstandard."
L["Anchor, growth, icons per row, duration and stack text, textured borders and dispel rings. Target and focus get Purgeable Buff Glow."] = "Anker, Wachstum, Symbole pro Reihe, Dauer- und Stapeltext, texturierte Rahmen und Bannringe. Ziel und Fokus erhalten Leuchten für reinigbare Stärkungszauber."
L["Every combat indicator style now shows, and highlighted portraits fit their shape instead of overflowing it."] = "Jeder Stil des Kampfindikators wird jetzt angezeigt, und hervorgehobene Porträts passen in ihre Form, statt überzulaufen."
L["Player, target, focus and boss health bars show estimated damage shields with Retail's Absorb Style, Opacity, Color, Placement, Show Overshield and Show on Boss Frames"] = "Gesundheitsleisten von Spieler, Ziel, Fokus und Boss zeigen geschätzte Schadensschilde mit Absorptions Stil, Deckkraft, Farbe, Platzierung, Überhangschild anzeigen und Auf Bossfenstern anzeigen aus Retail"
L["Mana or Mana + Form Power, with a separate form bar"] = "Mana oder Mana + Gestaltressource, mit einer separaten Gestaltleiste"
L["Threat %, a pet power bar and the pet happiness icon"] = "Bedrohung %, eine Ressourcenleiste für den Begleiter und das Glückssymbol des Begleiters"
L["Pooled aura indicators on the health bar with Use Indicator Layout"] = "Gebündelte Aurenindikatoren auf der Gesundheitsleiste mit Indikator-Layout verwenden"
L["Fill, full, gradient and sharp gradient overlays in the dispel color"] = "Füllung, Voll, Farbverlauf und scharfer Farbverlauf als Überlagerungen in der Bannfarbe"
L["Under Classic WoW UI and Blizzard Style, the leader crown sits on the portrait's top corner, as on the original frames, instead of inside the health bar."] = "Unter Klassisches WoW UI und Blizzard Stil sitzt die Anführerkrone an der oberen Ecke des Porträts, wie bei den Originalfenstern, statt in der Gesundheitsleiste."
L["The party leader icon on unit frames shows on the leader only instead of on several party members."] = "Das Symbol des Gruppenanführers auf Einheitenfenstern erscheint nur beim Anführer statt bei mehreren Gruppenmitgliedern."
L["Set Focus and Clear Focus in the unit frame right-click menu work out of combat without the 'blocked from an action' popup; in combat they are hidden."] = "Fokus setzen und Fokus entfernen im Rechtsklickmenü der Einheitenfenster funktionieren außerhalb des Kampfes ohne das Popup 'von einer Aktion blockiert'; im Kampf sind sie ausgeblendet."
L["Unit frame bars and portraits no longer get moved into scroll frames when !!!ClassicAPI is installed."] = "Leisten und Porträts der Einheitenfenster werden nicht mehr in Scrollrahmen verschoben, wenn !!!ClassicAPI installiert ist."
L["Important Cast Glow is hidden for target and focus cast bars; the Wrath client cannot tell which spells are important."] = "Leuchten wichtiger Zauber ist für die Zauberleisten von Ziel und Fokus ausgeblendet; der Wrath-Client kann nicht erkennen, welche Zauber wichtig sind."
L["Channel cast bars show the spell's name instead of \"Channeling\"."] = "Kanalisierte Zauberleisten zeigen den Namen des Zaubers statt \"Channeling\"."
L["Boss frames now update health, power and text while the boss is not your target or focus."] = "Bossfenster aktualisieren jetzt Gesundheit, Ressource und Text, während der Boss nicht dein Ziel oder Fokus ist."
L["Visibility conditions (combat, group, and hiding without a target) now apply to the frames instead of stopping with an error, so the Visibility menu's boxes also tick right away."] = "Sichtbarkeitsbedingungen (Kampf, Gruppe und Ausblenden ohne Ziel) gelten jetzt für die Fenster, statt mit einem Fehler abzubrechen, sodass die Kästchen im Sichtbarkeitsmenü auch sofort angehakt werden."
L["Classic WoW UI power bars now stay inside the frame art: the art's rim draws over the power bar as it does over the health bar."] = "Ressourcenleisten von Klassisches WoW UI bleiben jetzt innerhalb der Fenstergrafik: der Rand der Grafik wird über die Ressourcenleiste gezeichnet, wie über die Gesundheitsleiste."
L["Classic WoW UI now gives every unit frame the original green health bar instead of class colors. Returning to the EllesmereUI look restores your colors."] = "Klassisches WoW UI gibt jetzt jedem Einheitenfenster die originale grüne Gesundheitsleiste statt Klassenfarben. Die Rückkehr zum EllesmereUI-Aussehen stellt deine Farben wieder her."
L["Classic WoW UI power bars use the original game colors (deep blue mana, red rage, yellow energy) instead of the EllesmereUI palette. Other looks keep the palette."] = "Ressourcenleisten von Klassisches WoW UI nutzen die originalen Spielfarben (tiefblaues Mana, rote Wut, gelbe Energie) statt der EllesmereUI-Palette. Andere Aussehen behalten die Palette."
L["Text outlines now apply to the live frames, not only the options preview."] = "Textkonturen gelten jetzt für die Live-Fenster, nicht nur für die Vorschau in den Optionen."
L["Unit frames no longer fail to load on setups whose mask textures come back empty (absorb bar error at login)."] = "Einheitenfenster scheitern nicht mehr beim Laden auf Setups, deren Maskentexturen leer zurückkommen (Absorptionsleistenfehler beim Einloggen)."
L["Icons shown by spell ID now show the right icon or a question mark, never an empty square."] = "Per Zauber-ID angezeigte Symbole zeigen jetzt das richtige Symbol oder ein Fragezeichen, nie ein leeres Quadrat."
L["The faction indicator no longer errors in mercenary mode, and Retail-only PvP styles use the Wrath PvP icon."] = "Der Fraktionsindikator wirft im Söldnermodus keinen Fehler mehr, und reine Retail-PvP-Stile nutzen das PvP-Symbol von Wrath."
L["Level text no longer errors with Font not set when frames are first created."] = "Der Stufentext wirft beim ersten Erstellen der Fenster keinen Fehler Font not set mehr."
L["Like Retail 9.4, the Experience Bar section opens with XP Bar Style: EllesmereUI for the EUI bar, Luxthos for the EUI bar in the Luxthos WeakAura layout, or Blizz Default for Blizzard's own XP and reputation bars. It replaces Enable Experience Bar and the Apply Luxthos Layout button."] = "Wie in Retail 9.4 öffnet sich der Bereich Erfahrungsleiste mit EP-Leistenstil: EllesmereUI für die EUI-Leiste, Luxthos für die EUI-Leiste im Luxthos-WeakAura-Layout oder Blizz Standard für die eigenen EP- und Rufleisten von Blizzard. Er ersetzt Erfahrungsleiste aktivieren und die Taste Luxthos-Layout anwenden."
L["Like Retail 9.4, any horizontal bar can show the classic gryphons at its left end, right end or both, from the End Caps menu at the end of LAYOUT. The cog sets their size and offsets, and Apply to All copies them to every bar. The live preview shows them too."] = "Wie in Retail 9.4 kann jede horizontale Leiste die klassischen Greifen am linken Ende, rechten Ende oder an beiden zeigen, über das Menü Endkappen am Ende von LAYOUT. Das Zahnrad legt ihre Größe und Versätze fest, und Auf alle anwenden kopiert sie auf jede Leiste. Die Live-Vorschau zeigt sie ebenfalls."
L["The XP bar gets Retail's Quest XP Overlay (completed quests in green, incomplete in gold), dividers with Smart Ticks, gradient fills, background and rested colors, and seven text positions showing values, completed quest XP, XP per hour, time to level and time played. Apply Luxthos Layout recreates the popular Luxthos XP bar WeakAura, with Show at Max Level, a spark and rested XP after quest XP."] = "Die EP-Leiste erhält die Retail-Quest-EP-Überlagerung (abgeschlossene Quests grün, unvollständige golden), Trennlinien mit Intelligente Markierungen, Farbverlaufsfüllungen, Hintergrund- und Erholungsfarben sowie sieben Textpositionen mit Werten, EP aus abgeschlossenen Quests, EP pro Stunde, Zeit bis zum Stufenaufstieg und gespielter Zeit. Luxthos-Layout anwenden bildet die beliebte Luxthos-EP-Leisten-WeakAura nach, mit Auf Höchststufe anzeigen, einem Funken und erholten EP nach Quest-EP."
L["Buttons holding an equipped item, such as a trinket, can show a border in its rarity color. Off by default."] = "Tasten mit einem angelegten Gegenstand, etwa einem Schmuckstück, können einen Rahmen in dessen Seltenheitsfarbe zeigen. Standardmäßig aus."
L["Four extra bars, off by default, each with its own keybinds, Unlock Mode mover and the full Bar Display settings. Warriors, Druids, Rogues and Priests see which stance or form shares a bar's slots."] = "Vier zusätzliche Leisten, standardmäßig aus, jede mit eigenen Tastenbelegungen, Mover im Freigabemodus und den vollständigen Einstellungen der Leistenanzeige. Krieger, Druiden, Schurken und Priester sehen, welche Haltung oder Gestalt die Plätze einer Leiste teilt."
L["Circle and Portrait draw round icons, Diamond, Hexagon and Shield crop the icon to the shape, and Square and Curved Square add a shaped outline. Set per bar, including pet and stance."] = "Kreis und Porträt zeichnen runde Symbole, Diamant, Sechseck und Schild schneiden das Symbol auf die Form zu, und Quadratisch und Abgerundetes Quadrat fügen eine geformte Kontur hinzu. Pro Leiste einstellbar, einschließlich Begleiter und Haltung."
L["Type /kb, hover a button and press a key to bind it, including modifiers, mouse buttons and the wheel. Right-click clears; Cancel or Esc undoes."] = "Gib /kb ein, fahre über eine Taste und drücke eine Taste, um sie zu belegen, einschließlich Modifikatoren, Maustasten und Mausrad. Rechtsklick löscht; Abbrechen oder Esc macht rückgängig."
L["Per-bar text, borders, backgrounds, orientation and growth, the Retail button animations and visibility engine, and Bar 1 modifier paging."] = "Text, Rahmen, Hintergründe, Ausrichtung und Wachstum pro Leiste, die Retail-Tastenanimationen und die Sichtbarkeitsengine sowie Modifikator-Seitenwechsel für Leiste 1."
L["Shift+1 shows as S1, Control+1 as C1, mouse buttons as M4 and the wheel as MwU/MwD"] = "Shift+1 wird als S1 angezeigt, Control+1 als C1, Maustasten als M4 und das Mausrad als MwU/MwD"
L["Shrink the bag bar to a single backpack button"] = "Verkleinere die Taschenleiste auf eine einzelne Rucksacktaste"
L["Square micro menu and bag bar, flat XP and reputation bars and movable buffs and debuffs"] = "Quadratisches Mikromenü und Taschenleiste, flache EP- und Rufleisten und bewegbare Stärkungs- und Schwächungszauber"
L["Bar 1 paging arrows change the page without the \"blocked from an action only available to the Blizzard UI\" message."] = "Die Seitenpfeile von Leiste 1 wechseln die Seite ohne die Meldung \"blocked from an action only available to the Blizzard UI\"."
L["Changing stance no longer reveals a duplicate Blizzard stance and pet bar."] = "Ein Haltungswechsel zeigt keine doppelte Blizzard-Haltungs- und Begleiterleiste mehr."
L["Spells can be dropped on Bar 1 while the Blizzard bar art is hidden."] = "Zauber können auf Leiste 1 abgelegt werden, während die Blizzard-Leistengrafik ausgeblendet ist."
L["Player Buffs keep growing downward as rows are added."] = "Stärkungszauber des Spielers wachsen weiter nach unten, wenn Reihen hinzukommen."
L["The XP and reputation bars no longer error on their first update."] = "Die EP- und Rufleisten werfen bei ihrer ersten Aktualisierung keinen Fehler mehr."
L["Create Soulstone reminders, including custom spell reminders, only appear for Warlocks."] = "Erinnerungen für Seelenstein herstellen, einschließlich eigener Zaubererinnerungen, erscheinen nur für Hexenmeister."
L["A Holy-only reminder for your Seal of Wisdom, including when another seal is active."] = "Eine Erinnerung nur für Heilig an dein Siegel der Weisheit, auch wenn ein anderes Siegel aktiv ist."
L["One click casts your group buff, such as Fortitude, Gift of the Wild or Arcane Brilliance, at its highest rank on the first member missing it."] = "Ein Klick wirkt deinen Gruppenstärkungszauber, etwa Seelenstärke, Gabe der Wildnis oder Arkane Brillanz, im höchsten Rang auf das erste Mitglied, dem er fehlt."
L["Auras, presences, aspects, shields, weapon imbues, poisons, pets, Soulstone and Healthstone, plus flask, elixir and food with bag counts."] = "Auren, Präsenzen, Aspekte, Schilde, Waffenverzauberungen, Gifte, Begleiter, Seelenstein und Gesundheitsstein sowie Fläschchen, Elixier und Essen mit Taschenanzahl."
L["Reminder sounds include SharedMedia sounds, even from packs that load later"] = "Erinnerungssounds enthalten SharedMedia-Sounds, auch aus Paketen, die später geladen werden"
L["World, normal and heroic dungeons and raids, or in combat, with Show Below timers"] = "Welt, normale und heroische Dungeons und Schlachtzüge oder im Kampf, mit Timern für Darunter anzeigen"
L["Talent reminders for Wrath zones and your current instance"] = "Talenterinnerungen für Wrath-Zonen und deine aktuelle Instanz"
L["Your own aura ID reminders and a healer mana Ready Check Warning"] = "Deine eigenen Erinnerungen per Auren-ID und eine Manawarnung bei Bereitschaftsabfrage für Heiler"
L["Middle-click hides a reminder until the next loading screen"] = "Mittelklick blendet eine Erinnerung bis zum nächsten Ladebildschirm aus"
L["Turning off Runeforging now hides the Death Knight rune reminder."] = "Das Ausschalten von Runenschmieden blendet jetzt die Runenerinnerung des Todesritters aus."
L["Adding zones to an older talent reminder no longer errors, and the new zones apply right away."] = "Das Hinzufügen von Zonen zu einer älteren Talenterinnerung wirft keinen Fehler mehr, und die neuen Zonen gelten sofort."
L["A coin in the bag header marks items as junk: click it, then click items. Grey and marked items go to a Junk category, and a Sell Junk button appears next to the coin at merchants. Its cog adds a coin badge on marked items."] = "Eine Münze in der Taschenkopfzeile markiert Gegenstände als Müll: klicke sie an und dann auf Gegenstände. Graue und markierte Gegenstände kommen in eine Kategorie Müll, und bei Händlern erscheint neben der Münze eine Taste Müll verkaufen. Ihr Zahnrad fügt markierten Gegenständen ein Münzabzeichen hinzu."
L["Bag keybinds open and close the existing layout during combat. Layout refreshes wait until combat ends."] = "Tastenbelegungen für Taschen öffnen und schließen das bestehende Layout im Kampf. Layoutaktualisierungen warten bis zum Kampfende."
L["A sidebar with All Items, OneBag and MultiBag views, pinned and recent items, Retail categories for Wrath items and your own categories."] = "Eine Seitenleiste mit den Ansichten Alle Gegenstände, Einzeltasche und Mehrfachtasche, angehefteten und neuen Gegenständen, Retail-Kategorien für Wrath-Gegenstände und deinen eigenen Kategorien."
L["OneBag merges stacks and sorts by bag type, MultiBag sorts each bag, with Sort to Bottom and Randomize."] = "Einzeltasche führt Stapel zusammen und sortiert nach Taschentyp, Mehrfachtasche sortiert jede Tasche, mit Nach unten sortieren und Zufällig anordnen."
L["A cog beside the search opens the Bags options, or the Bank page at the bank"] = "Ein Zahnrad neben der Suche öffnet die Taschenoptionen oder bei der Bank die Seite Bank"
L["Each saved character in the Characters list has an x to delete its data"] = "Jeder gespeicherte Charakter in der Liste Charaktere hat ein x, um seine Daten zu löschen"
L["Quality borders, quest marks, item level, BoE text, set names and dimmed junk"] = "Qualitätsrahmen, Questmarkierungen, Gegenstandsstufe, BoE-Text, Setnamen und abgedunkelter Müll"
L["Group the bank by category, with a sidebar"] = "Gruppiere die Bank nach Kategorie, mit einer Seitenleiste"
L["With Enable Bags off, the default bag functions are no longer replaced, avoiding blocked action errors from tainted bag code."] = "Mit deaktiviertem Taschen aktivieren werden die Standard-Taschenfunktionen nicht mehr ersetzt, was Fehler durch blockierte Aktionen aus verseuchtem Taschencode vermeidet."
L["Opening the Characters list no longer errors."] = "Das Öffnen der Liste Charaktere wirft keinen Fehler mehr."
L["Gold sale ads with websites or cash prices, including 5000G=20 bucks and disguised W.W.W addresses, are filtered by default in your selected chat scopes."] = "Goldverkaufswerbung mit Webseiten oder Bargeldpreisen, einschließlich 5000G=20 bucks und getarnter W.W.W-Adressen, wird standardmäßig in deinen gewählten Chatbereichen gefiltert."
L["Unsupported server channel notices such as NOT_IN_LFG no longer cause the native chat formatter to error."] = "Nicht unterstützte Serverkanal-Hinweise wie NOT_IN_LFG lassen den nativen Chatformatierer keinen Fehler mehr werfen."
L["Optional spam filtering with a repeat window, sender matching and public, group or whisper controls."] = "Optionale Spamfilterung mit Wiederholungsfenster, Absenderabgleich und Steuerung für öffentlich, Gruppe oder Flüstern."
L["Background, divider, input position, Retail border and tabs over the native dock, plus a sidebar with friends, guild, copy, channels and settings."] = "Hintergrund, Trenner, Eingabeposition, Retail-Rahmen und Reiter über dem nativen Dock, dazu eine Seitenleiste mit Freunden, Gilde, Kopieren, Kanälen und Einstellungen."
L["Retail timestamps, short channel names, class colored names, link tooltips, whisper sounds, saved chat history and Retail URL and copy windows."] = "Retail-Zeitstempel, kurze Kanalnamen, Namen in Klassenfarbe, Link-Tooltips, Flüstersounds, gespeicherter Chatverlauf sowie Retail-URL- und Kopierfenster."
L["Show Hidden Messages lists the last 200 lines the spam filter hid this session, with time, reason, channel and sender. Clear Filter History is now Reset Repeat Memory."] = "Versteckte Nachrichten anzeigen listet die letzten 200 Zeilen, die der Spamfilter in dieser Sitzung ausgeblendet hat, mit Zeit, Grund, Kanal und Absender. Filterverlauf löschen heißt jetzt Wiederholungsspeicher zurücksetzen."
L["The trade ad preset also hides LFW (looking for work) crafting ads."] = "Die Voreinstellung für Handelswerbung blendet auch LFW-Handwerksangebote (looking for work) aus."
L["Right-click the chat in Unlock Mode to open its Display settings"] = "Rechtsklicke den Chat im Freigabemodus, um seine Anzeigeeinstellungen zu öffnen"
L["Restyled chat bubbles with per-channel toggles and hiding in instances"] = "Neu gestaltete Sprechblasen mit Schaltern pro Kanal und Ausblenden in Instanzen"
L["The chat fades after a delay and comes back on mouseover"] = "Der Chat verblasst nach einer Verzögerung und kehrt beim Überfahren mit der Maus zurück"
L["Copy Chat copies the chat tab you are looking at instead of the last tab you right-clicked, which could show \"(No chat history)\"."] = "Chat kopieren kopiert den Chatreiter, den du gerade ansiehst, statt des zuletzt rechtsgeklickten Reiters, der \"(No chat history)\" zeigen konnte."
L["Fixed a \"SetPoint(): is dependent on this\" error when styling some NPC chat bubbles."] = "Ein Fehler \"SetPoint(): is dependent on this\" beim Gestalten mancher NPC-Sprechblasen wurde behoben."
L["The guild recruitment filter no longer hides raid ads that mention a guild, such as \"<Frost> LF 1 heal ICC25\"; only LF guild phrases count."] = "Der Gildenrekrutierungsfilter blendet keine Schlachtzugsanzeigen mehr aus, die eine Gilde erwähnen, etwa \"<Frost> LF 1 heal ICC25\"; nur Phrasen zur Gildensuche zählen."
L["GM whispers and messages are never hidden by the spam filter."] = "GM-Flüsternachrichten und -Nachrichten werden nie vom Spamfilter ausgeblendet."
L["Spam filter keywords ignore case for accented letters too, so promoção also hides PROMOÇÃO."] = "Schlüsselwörter des Spamfilters ignorieren Groß- und Kleinschreibung auch bei Akzentbuchstaben, sodass promoção auch PROMOÇÃO ausblendet."
L["The trade ad and guild recruitment filters follow the Public Chat setting, and the spam filter does no work while every filter is off."] = "Die Filter für Handelswerbung und Gildenrekrutierung folgen der Einstellung Öffentlicher Chat, und der Spamfilter arbeitet nicht, solange alle Filter aus sind."
L["The sidebar shows on first load, and tabs and toggles update right away."] = "Die Seitenleiste erscheint beim ersten Laden, und Reiter und Schalter aktualisieren sich sofort."
L["The main chat keeps its Unlock Mode position instead of being reset by the dock."] = "Der Hauptchat behält seine Position aus dem Freigabemodus, statt vom Dock zurückgesetzt zu werden."
L["A saved chat opacity of 0 resets once to the Retail default."] = "Eine gespeicherte Chat-Deckkraft von 0 wird einmalig auf den Retail-Standard zurückgesetzt."
L["Square, rectangular, circle and textured circle maps, with border size, opacity, textured styles and custom, accent or class colors."] = "Quadratische, rechteckige, runde und texturierte runde Karten, mit Rahmengröße, Deckkraft, texturierten Stilen und eigenen, Akzent- oder Klassenfarben."
L["Addon buttons collect into the Retail flyout with a grid, grow direction and Shift-drag Free Move."] = "Addon-Tasten sammeln sich im Retail-Ausklappmenü mit Raster, Wachstumsrichtung und freiem Bewegen per Umschalt-Ziehen."
L["A vanilla ring and zone banner with native zoom buttons"] = "Ein Vanilla-Ring und Zonenbanner mit nativen Zoomtasten"
L["Clock and zone boxes in ten positions, plus coordinates, FPS and latency, and difficulty text"] = "Uhr- und Zonenfelder in zehn Positionen, dazu Koordinaten, FPS und Latenz sowie Schwierigkeitstext"
L["Guild and friends at a glance; left-click whispers, right-click invites"] = "Gilde und Freunde auf einen Blick; Linksklick flüstert, Rechtsklick lädt ein"
L["Menu actions open Blizzard windows through secure calls, avoiding blocked action errors."] = "Menüaktionen öffnen Blizzard-Fenster über sichere Aufrufe und vermeiden so Fehler durch blockierte Aktionen."
L["Pick Classic WoW UI for Damage Meters on the Style page: each window gets the classic tooltip border, a tooltip header band and vanilla header icons, and keeps every EllesmereUI meter feature."] = "Wähle Klassisches WoW UI für Schadensmeter auf der Seite Stil: jedes Fenster erhält den klassischen Tooltip-Rahmen, ein Tooltip-Kopfband und Vanilla-Kopfzeilensymbole und behält jede EllesmereUI Meterfunktion."
L["A spell's breakdown tooltip shows its Spell ID, and each spell row in the detailed window ends with its ID."] = "Der Aufschlüsselungstooltip eines Zaubers zeigt seine Zauber-ID, und jede Zauberzeile im Detailfenster endet mit ihrer ID."
L["Consumed shield absorbs count toward Healing Done and HPS when the caster can be identified, with an Absorbs Done view."] = "Verbrauchte Schildabsorptionen zählen zu Heilung verursacht und HPS, wenn der Zaubernde ermittelt werden kann, mit einer Ansicht für verursachte Absorptionen."
L["Flat body, accent header, Atrocity bars and header icons for Settings, Segment, Meter Type and Reset, with up to five windows."] = "Flacher Körper, Akzent-Kopfzeile, Atrocity-Leisten und Kopfzeilensymbole für Einstellungen, Segment, Messertyp und Zurücksetzen, mit bis zu fünf Fenstern."
L["Up to 15 spells and the top three targets on hover, death recaps with health at each hit, and a per-player focus view."] = "Bis zu 15 Zauber und die drei häufigsten Ziele beim Überfahren, Todesrückblicke mit Gesundheit bei jedem Treffer und eine Fokusansicht pro Spieler."
L["SharedMedia bar textures load whether a profile stores them in Damage Meters or EllesmereUI format"] = "SharedMedia-Leistentexturen werden geladen, egal ob ein Profil sie im Format von Schadensmeter oder EllesmereUI speichert"
L["An icon strip and bar window of your casts, including failed and interrupted ones"] = "Eine Symbolleiste und ein Leistenfenster deiner Zauber, einschließlich fehlgeschlagener und unterbrochener"
L["A standalone combat timer with its own Unlock Mode element"] = "Ein freistehender Kampftimer mit eigenem Element im Freigabemodus"
L["Windows snap to each other; locked windows cannot move, resize or close"] = "Fenster rasten aneinander ein; gesperrte Fenster können nicht bewegt, skaliert oder geschlossen werden"
L["Keybinds for Reset Data and Show / Hide Windows"] = "Tastenbelegungen für Daten zurücksetzen und Fenster anzeigen / ausblenden"
L["Specialization icons from talent data and paced group inspection"] = "Spezialisierungssymbole aus Talentdaten und dosiertes Betrachten der Gruppe"
L["Load an action menu only in your primary or secondary talent group, and let two menus share one keybind across specs."] = "Lade ein Aktionsmenü nur in deiner primären oder sekundären Talentgruppe und lasse zwei Menüs eine Tastenbelegung über Spezialisierungen hinweg teilen."
L["Hold a key, point or scroll to choose, release to fire. Up to 16 palettes of 20 entries in ring, arc, fan or grid layouts."] = "Halte eine Taste, zeige oder scrolle zur Auswahl, lasse los zum Auslösen. Bis zu 16 Paletten mit 20 Einträgen in Ring-, Bogen-, Fächer- oder Rasterlayouts."
L["An Action Menu entry fans out up to 8 actions from another palette, one level out from the ring."] = "Ein Aktionsmenü-Eintrag fächert bis zu 8 Aktionen aus einer anderen Palette auf, eine Ebene außerhalb des Rings."
L["Accent, class or custom color for the selected entry, needle and nested highlight"] = "Akzent-, Klassen- oder eigene Farbe für den ausgewählten Eintrag, die Nadel und die verschachtelte Hervorhebung"
L["Set the gap between a nested menu and its entry, and the nested icon size"] = "Lege den Abstand zwischen einem verschachtelten Menü und seinem Eintrag sowie die Größe verschachtelter Symbole fest"
L["Reverse which way a wheel tick moves the selection"] = "Kehrt um, in welche Richtung ein Mausradschritt die Auswahl bewegt"
L["Assign Key captures the next key with modifiers and asks before rebinding"] = "Taste zuweisen erfasst die nächste Taste mit Modifikatoren und fragt vor dem Neubelegen nach"
L["Keep the menu open on release and fire with a Select key"] = "Hält das Menü beim Loslassen offen und löst mit einer Auswahltaste aus"
L["Red when out of range, blue when short of power, grey when unusable"] = "Rot außer Reichweite, blau bei zu wenig Ressource, grau wenn unbenutzbar"
L["Elite and rare marks. Always in the same slot as the Quest Indicator."] = "Elite- und Rar-Markierungen. Immer im selben Slot wie der Questindikator."
L["Marks mobs for your active quests. Always in the same slot as the Rare Indicator."] = "Markiert Gegner deiner aktiven Quests. Immer im selben Slot wie der Rar-Indikator."
L["Quest Indicator"] = "Questindikator"
L["Rare and Quest Indicators"] = "Rar- und Questindikatoren"
L["Rare Indicator"] = "Rar-Indikator"
L["Rare/Quest Indicator"] = "Rar-/Questindikator"
L["The Boss Icon slot is now the Retail Rare/Quest Indicator. It marks elites and rares, and mobs your active quests still need. Pick Rare Indicator, Quest Indicator or both in Core Positions; the slot cog adds Show In Instances."] = "Der Slot Boss-Symbol ist jetzt der Rar-/Questindikator aus Retail. Er markiert Elite- und seltene Gegner sowie Gegner, die deine aktiven Quests noch brauchen. Wähle in den Kernpositionen Rar-Indikator, Questindikator oder beide; das Zahnrad des Slots bietet zusätzlich In Instanzen anzeigen."
L["Crowd Control"] = "Kontrollverlust (CC)"
L["Crowd Control Slot"] = "Slot für Kontrollverlust"
L["Debuffs + CC"] = "Schwächungszauber + CC"
L["Crowd control on enemies (stuns, fears, polymorphs, roots, silences) gets its own Core Positions slot, from any caster, as on Retail. Or pick Debuffs + CC to show it first in the debuff row."] = "Kontrollverlust auf Gegnern (Betäubungen, Furcht, Verwandlungen, Wurzeln, Stille) bekommt einen eigenen Slot in den Kernpositionen, von jedem Zaubernden, wie in Retail. Oder wähle Schwächungszauber + CC, um ihn zuerst in der Schwächungsreihe anzuzeigen."
L["Learn %d skill%s for %s"] = "Lerne %1$d Fertigkeit(en) für %3$s"
